--
-- Name: validate_pick_reversal(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_pick_reversal() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    target RECORD;
    transaction_row RECORD;
BEGIN
    SELECT confirmation.inventory_owner_id,
           confirmation.facility_id,
           confirmation.task_id,
           confirmation.pick_task_content_id,
           confirmation.order_release_id,
           confirmation.order_id,
           confirmation.order_item_id,
           confirmation.reservation_id,
           confirmation.source_inventory_allocation_id,
           confirmation.destination_inventory_allocation_id,
           confirmation.source_inventory_balance_id,
           confirmation.destination_inventory_balance_id,
           confirmation.source_location_id,
           confirmation.destination_location_id,
           confirmation.source_license_plate_id,
           confirmation.destination_license_plate_id,
           confirmation.item_batch_id,
           confirmation.item_id,
           confirmation.uom,
           confirmation.inventory_status,
           confirmation.picked_qty,
           confirmation.confirmed_at,
           content.planned_qty,
           content.state AS content_state,
           content.completed_at AS content_completed_at,
           task.status AS task_status,
           task.completed_at AS task_completed_at,
           order_header.status AS order_status,
           order_header.revision AS order_revision,
           source_allocation.status AS source_allocation_status,
           source_allocation.deleted AS source_allocation_deleted,
           source_allocation.execution_stage AS source_execution_stage,
           staged_allocation.status AS staged_allocation_status,
           staged_allocation.deleted AS staged_allocation_deleted,
           staged_allocation.execution_stage AS staged_execution_stage,
           source_balance.qty_on_hand AS source_on_hand,
           staged_balance.qty_on_hand AS staged_on_hand,
           staged_balance.qty_reserved AS staged_reserved
    INTO target
    FROM public.pick_confirmations confirmation
    INNER JOIN public.pick_task_contents content
      ON content.tenant_id = confirmation.tenant_id
     AND content.inventory_owner_id = confirmation.inventory_owner_id
     AND content.facility_id = confirmation.facility_id
     AND content.task_id = confirmation.task_id
     AND content.id = confirmation.pick_task_content_id
    INNER JOIN public.pick_tasks task
      ON task.tenant_id = confirmation.tenant_id
     AND task.inventory_owner_id = confirmation.inventory_owner_id
     AND task.facility_id = confirmation.facility_id
     AND task.id = confirmation.task_id
    INNER JOIN public.orders order_header
      ON order_header.tenant_id = confirmation.tenant_id
     AND order_header.inventory_owner_id = confirmation.inventory_owner_id
     AND order_header.id = confirmation.order_id
    INNER JOIN public.inventory_allocations source_allocation
      ON source_allocation.tenant_id = confirmation.tenant_id
     AND source_allocation.inventory_owner_id = confirmation.inventory_owner_id
     AND source_allocation.id = confirmation.source_inventory_allocation_id
    INNER JOIN public.inventory_allocations staged_allocation
      ON staged_allocation.tenant_id = confirmation.tenant_id
     AND staged_allocation.inventory_owner_id = confirmation.inventory_owner_id
     AND staged_allocation.id = confirmation.destination_inventory_allocation_id
    INNER JOIN public.inventory_balances source_balance
      ON source_balance.tenant_id = confirmation.tenant_id
     AND source_balance.inventory_owner_id = confirmation.inventory_owner_id
     AND source_balance.id = confirmation.source_inventory_balance_id
    INNER JOIN public.inventory_balances staged_balance
      ON staged_balance.tenant_id = confirmation.tenant_id
     AND staged_balance.inventory_owner_id = confirmation.inventory_owner_id
     AND staged_balance.id = confirmation.destination_inventory_balance_id
    WHERE confirmation.tenant_id = NEW.tenant_id
      AND confirmation.inventory_owner_id = NEW.inventory_owner_id
      AND confirmation.id = NEW.pick_confirmation_id
    FOR UPDATE OF content, task, order_header, source_allocation,
                  staged_allocation, source_balance, staged_balance;

    IF target.task_id IS NULL THEN
        RAISE EXCEPTION 'pick confirmation does not exist'
            USING ERRCODE = '23503';
    END IF;

    IF target.inventory_owner_id IS DISTINCT FROM NEW.inventory_owner_id
       OR target.facility_id IS DISTINCT FROM NEW.facility_id
       OR target.task_id IS DISTINCT FROM NEW.task_id
       OR target.pick_task_content_id IS DISTINCT FROM NEW.pick_task_content_id
       OR target.order_release_id IS DISTINCT FROM NEW.order_release_id
       OR target.order_id IS DISTINCT FROM NEW.order_id
       OR target.order_item_id IS DISTINCT FROM NEW.order_item_id
       OR target.reservation_id IS DISTINCT FROM NEW.reservation_id
       OR target.source_inventory_allocation_id IS DISTINCT FROM NEW.source_inventory_allocation_id
       OR target.destination_inventory_allocation_id IS DISTINCT FROM NEW.staged_inventory_allocation_id
       OR target.source_inventory_balance_id IS DISTINCT FROM NEW.source_inventory_balance_id
       OR target.destination_inventory_balance_id IS DISTINCT FROM NEW.staged_inventory_balance_id
       OR target.source_location_id IS DISTINCT FROM NEW.source_location_id
       OR target.destination_location_id IS DISTINCT FROM NEW.staged_location_id
       OR target.source_license_plate_id IS DISTINCT FROM NEW.source_license_plate_id
       OR target.destination_license_plate_id IS DISTINCT FROM NEW.staged_license_plate_id
       OR target.item_batch_id IS DISTINCT FROM NEW.item_batch_id
       OR target.item_id IS DISTINCT FROM NEW.item_id
       OR target.uom IS DISTINCT FROM NEW.uom
       OR target.inventory_status IS DISTINCT FROM NEW.inventory_status
       OR target.picked_qty IS DISTINCT FROM NEW.reversed_qty
       OR target.planned_qty IS DISTINCT FROM NEW.reversed_qty
    THEN
        RAISE EXCEPTION 'pick reversal does not match the immutable confirmation'
            USING ERRCODE = '23514';
    END IF;

    IF target.order_status NOT IN ('processing', 'awaiting packing')
       OR target.order_revision IS DISTINCT FROM NEW.expected_order_revision
       OR NEW.resulting_order_revision <> NEW.expected_order_revision + 1
       OR target.content_state <> 'completed'
       OR target.content_completed_at IS DISTINCT FROM target.confirmed_at
       OR target.task_status <> 'completed'
       OR target.task_completed_at IS DISTINCT FROM target.confirmed_at
       OR target.source_allocation_status <> 'fulfilled'
       OR target.source_allocation_deleted IS DISTINCT FROM target.confirmed_at
       OR target.source_execution_stage <> 'pick_source'
       OR target.staged_allocation_status <> 'allocated'
       OR target.staged_allocation_deleted IS NOT NULL
       OR target.staged_execution_stage <> 'staged'
       OR target.staged_on_hand < NEW.reversed_qty
       OR target.staged_reserved < NEW.reversed_qty
       OR NEW.reversed_at < target.confirmed_at
    THEN
        RAISE EXCEPTION 'pick confirmation is not reversible in its current execution state'
            USING ERRCODE = '55000';
    END IF;

    IF EXISTS (
        SELECT 1 FROM public.pick_shortages shortage
        WHERE shortage.tenant_id = NEW.tenant_id
          AND shortage.inventory_owner_id = NEW.inventory_owner_id
          AND (
              shortage.pick_confirmation_id = NEW.pick_confirmation_id
              OR shortage.pick_task_content_id = NEW.pick_task_content_id
          )
    ) THEN
        RAISE EXCEPTION 'shortage-backed picks require shortage recovery'
            USING ERRCODE = '55000';
    END IF;

    IF EXISTS (
        SELECT 1 FROM public.packing_sessions session
        WHERE session.tenant_id = NEW.tenant_id
          AND session.inventory_owner_id = NEW.inventory_owner_id
          AND session.order_id = NEW.order_id
    ) THEN
        RAISE EXCEPTION 'pick reversal is unavailable after packing begins'
            USING ERRCODE = '55000';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM public.license_plates plate
        WHERE plate.tenant_id = NEW.tenant_id
          AND plate.inventory_owner_id = NEW.inventory_owner_id
          AND plate.facility_id = NEW.facility_id
          AND plate.id = NEW.staged_license_plate_id
          AND plate.location_id = NEW.staged_location_id
          AND plate.deleted IS NULL
    ) OR (
        NEW.source_license_plate_id IS NOT NULL
        AND NOT EXISTS (
            SELECT 1 FROM public.license_plates plate
            WHERE plate.tenant_id = NEW.tenant_id
              AND plate.inventory_owner_id = NEW.inventory_owner_id
              AND plate.facility_id = NEW.facility_id
              AND plate.id = NEW.source_license_plate_id
              AND plate.location_id = NEW.source_location_id
              AND plate.deleted IS NULL
        )
    ) THEN
        RAISE EXCEPTION 'pick reversal license plates are not at the recorded locations'
            USING ERRCODE = '55000';
    END IF;

    SELECT transaction.actor_user_id, transaction.transaction_type,
           transaction.reference_type, transaction.reference_id,
           transaction.operation, transaction.created
    INTO transaction_row
    FROM public.inventory_transactions transaction
    WHERE transaction.tenant_id = NEW.tenant_id
      AND transaction.inventory_owner_id = NEW.inventory_owner_id
      AND transaction.id = NEW.inventory_transaction_id;

    IF transaction_row.transaction_type IS NULL
       OR transaction_row.actor_user_id IS DISTINCT FROM NEW.reversed_by_user_id
       OR transaction_row.transaction_type <> 'move'
       OR transaction_row.reference_type <> 'pick_confirmation'
       OR transaction_row.reference_id IS DISTINCT FROM NEW.pick_confirmation_id
       OR transaction_row.operation <> 'picking.confirmation.reverse.v1'
       OR transaction_row.created IS DISTINCT FROM NEW.reversed_at
    THEN
        RAISE EXCEPTION 'pick reversal inventory transaction does not match the command'
            USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: require_pick_reversal_consistency(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.require_pick_reversal_consistency() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    entry_count BIGINT;
    entry_net BIGINT;
    source_entry_count BIGINT;
    staged_entry_count BIGINT;
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM public.orders order_header
        INNER JOIN public.pick_tasks task
          ON task.tenant_id = order_header.tenant_id
         AND task.inventory_owner_id = order_header.inventory_owner_id
         AND task.order_id = order_header.id
         AND task.id = NEW.task_id
        INNER JOIN public.pick_task_contents content
          ON content.tenant_id = task.tenant_id
         AND content.inventory_owner_id = task.inventory_owner_id
         AND content.facility_id = task.facility_id
         AND content.task_id = task.id
         AND content.id = NEW.pick_task_content_id
        INNER JOIN public.inventory_allocations source_allocation
          ON source_allocation.tenant_id = NEW.tenant_id
         AND source_allocation.inventory_owner_id = NEW.inventory_owner_id
         AND source_allocation.id = NEW.source_inventory_allocation_id
        INNER JOIN public.inventory_allocations staged_allocation
          ON staged_allocation.tenant_id = NEW.tenant_id
         AND staged_allocation.inventory_owner_id = NEW.inventory_owner_id
         AND staged_allocation.id = NEW.staged_inventory_allocation_id
        INNER JOIN public.inventory_balances source_balance
          ON source_balance.tenant_id = NEW.tenant_id
         AND source_balance.inventory_owner_id = NEW.inventory_owner_id
         AND source_balance.id = NEW.source_inventory_balance_id
        INNER JOIN public.inventory_balances staged_balance
          ON staged_balance.tenant_id = NEW.tenant_id
         AND staged_balance.inventory_owner_id = NEW.inventory_owner_id
         AND staged_balance.id = NEW.staged_inventory_balance_id
        WHERE order_header.tenant_id = NEW.tenant_id
          AND order_header.inventory_owner_id = NEW.inventory_owner_id
          AND order_header.id = NEW.order_id
          AND order_header.status = 'processing'
          AND order_header.revision = NEW.resulting_order_revision
          AND task.status = 'open'
          AND task.assigned_user_id IS NULL
          AND task.claimed_at IS NULL
          AND task.lease_expires_at IS NULL
          AND task.completed_at IS NULL
          AND content.state = 'pending'
          AND content.completed_at IS NULL
          AND source_allocation.status = 'allocated'
          AND source_allocation.deleted IS NULL
          AND source_allocation.modified IS NULL
          AND source_allocation.execution_stage = 'pick_source'
          AND source_allocation.inventory_balance_id = NEW.source_inventory_balance_id
          AND source_allocation.qty = NEW.reversed_qty
          AND staged_allocation.status = 'released'
          AND staged_allocation.deleted = NEW.reversed_at
          AND staged_allocation.modified = NEW.reversed_at
          AND staged_allocation.execution_stage = 'staged'
          AND staged_allocation.inventory_balance_id = NEW.staged_inventory_balance_id
          AND staged_allocation.qty = NEW.reversed_qty
          AND source_balance.qty_on_hand >= NEW.reversed_qty
          AND source_balance.qty_reserved >= NEW.reversed_qty
          AND staged_balance.qty_on_hand >= 0
          AND staged_balance.qty_reserved >= 0
    ) THEN
        RAISE EXCEPTION 'pick reversal does not reconcile with reopened work or inventory projections'
            USING ERRCODE = '23514';
    END IF;

    SELECT COUNT(*), COALESCE(SUM(entry.quantity_delta), 0)::BIGINT,
           COUNT(*) FILTER (
               WHERE entry.facility_id = NEW.facility_id
                 AND entry.location_id = NEW.source_location_id
                 AND entry.license_plate_id IS NOT DISTINCT FROM NEW.source_license_plate_id
                 AND entry.item_batch_id = NEW.item_batch_id
                 AND entry.item_id = NEW.item_id
                 AND entry.uom = NEW.uom
                 AND entry.status = NEW.inventory_status
                 AND entry.quantity_delta = NEW.reversed_qty
           ),
           COUNT(*) FILTER (
               WHERE entry.facility_id = NEW.facility_id
                 AND entry.location_id = NEW.staged_location_id
                 AND entry.license_plate_id = NEW.staged_license_plate_id
                 AND entry.item_batch_id = NEW.item_batch_id
                 AND entry.item_id = NEW.item_id
                 AND entry.uom = NEW.uom
                 AND entry.status = NEW.inventory_status
                 AND entry.quantity_delta = -NEW.reversed_qty
           )
    INTO entry_count, entry_net, source_entry_count, staged_entry_count
    FROM public.inventory_entries entry
    WHERE entry.tenant_id = NEW.tenant_id
      AND entry.inventory_owner_id = NEW.inventory_owner_id
      AND entry.transaction_id = NEW.inventory_transaction_id;

    IF entry_count <> 2 OR entry_net <> 0
       OR source_entry_count <> 1 OR staged_entry_count <> 1
    THEN
        RAISE EXCEPTION 'pick reversal inventory entries do not conserve reversed quantity'
            USING ERRCODE = '23514';
    END IF;

    RETURN NULL;
END;
$$;


--
-- Name: validate_order_release(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_order_release() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    location_matches BOOLEAN;
BEGIN
    SELECT EXISTS (
        SELECT 1
        FROM public.locations location
        WHERE location.tenant_id = NEW.tenant_id
          AND location.facility_id = NEW.facility_id
          AND location.id = NEW.destination_location_id
          AND location.deleted IS NULL
          AND location.active
          AND NOT location.pickable
          AND location.barcode IS NOT NULL
          AND location.barcode = btrim(location.barcode)
          AND location.barcode <> ''
          AND lower(location.type) IN ('staging', 'packing')
    ) INTO location_matches;

    IF NOT location_matches THEN
        RAISE EXCEPTION 'order release destination must be an active scannable staging or packing location'
            USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: validate_order_release_allocation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_order_release_allocation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    release_row RECORD;
    allocation_row RECORD;
    recovery_matches BOOLEAN;
BEGIN
    SELECT release.inventory_owner_id, release.facility_id, release.order_id
    INTO release_row
    FROM public.order_releases release
    WHERE release.tenant_id = NEW.tenant_id
      AND release.id = NEW.order_release_id;

    SELECT allocation.reservation_id, allocation.inventory_balance_id,
           allocation.facility_id, allocation.location_id,
           allocation.license_plate_id, allocation.item_batch_id,
           allocation.item_id, allocation.uom, allocation.inventory_status,
           allocation.qty, allocation.status, allocation.deleted,
           allocation.execution_stage,
           reservation.order_id, reservation.order_item_id,
           (source_location.deleted IS NULL
            AND source_location.active
            AND source_location.pickable
            AND source_location.barcode IS NOT NULL
            AND source_location.barcode = btrim(source_location.barcode)
            AND source_location.barcode <> '') AS source_is_ready
    INTO allocation_row
    FROM public.inventory_allocations allocation
    INNER JOIN public.inventory_reservations reservation
        ON reservation.tenant_id = allocation.tenant_id
       AND reservation.inventory_owner_id = allocation.inventory_owner_id
       AND reservation.id = allocation.reservation_id
    INNER JOIN public.locations source_location
        ON source_location.tenant_id = allocation.tenant_id
       AND source_location.facility_id = allocation.facility_id
       AND source_location.id = allocation.location_id
    WHERE allocation.tenant_id = NEW.tenant_id
      AND allocation.inventory_owner_id = NEW.inventory_owner_id
      AND allocation.id = NEW.allocation_id
    FOR SHARE OF allocation, reservation;

    IF release_row.order_id IS NULL OR allocation_row.order_id IS NULL THEN
        RAISE EXCEPTION 'release allocation dependencies do not exist'
            USING ERRCODE = '23503';
    END IF;

    IF NEW.inventory_owner_id IS DISTINCT FROM release_row.inventory_owner_id
       OR NEW.facility_id IS DISTINCT FROM release_row.facility_id
       OR NEW.order_id IS DISTINCT FROM release_row.order_id
       OR NEW.order_id IS DISTINCT FROM allocation_row.order_id
       OR NEW.order_item_id IS DISTINCT FROM allocation_row.order_item_id
       OR NEW.reservation_id IS DISTINCT FROM allocation_row.reservation_id
       OR NEW.inventory_balance_id IS DISTINCT FROM allocation_row.inventory_balance_id
       OR NEW.source_location_id IS DISTINCT FROM allocation_row.location_id
       OR NEW.source_license_plate_id IS DISTINCT FROM allocation_row.license_plate_id
       OR NEW.item_batch_id IS DISTINCT FROM allocation_row.item_batch_id
       OR NEW.item_id IS DISTINCT FROM allocation_row.item_id
       OR NEW.uom IS DISTINCT FROM allocation_row.uom
       OR NEW.inventory_status IS DISTINCT FROM allocation_row.inventory_status
       OR NEW.planned_qty IS DISTINCT FROM allocation_row.qty
       OR NEW.facility_id IS DISTINCT FROM allocation_row.facility_id
       OR allocation_row.status <> 'allocated'
       OR allocation_row.deleted IS NOT NULL
       OR allocation_row.execution_stage <> 'pick_source'
       OR allocation_row.inventory_status <> 'available'
       OR NOT allocation_row.source_is_ready
    THEN
        RAISE EXCEPTION 'release snapshot does not match its active allocation'
            USING ERRCODE = '23514';
    END IF;

    IF NEW.source_kind = 'shortage_recovery' THEN
        SELECT EXISTS (
            SELECT 1
            FROM public.pick_shortage_reallocation_runs run
            INNER JOIN public.pick_shortages shortage
              ON shortage.tenant_id = run.tenant_id
             AND shortage.inventory_owner_id = run.inventory_owner_id
             AND shortage.facility_id = run.facility_id
             AND shortage.order_release_id = run.order_release_id
             AND shortage.order_id = run.order_id
             AND shortage.order_item_id = run.order_item_id
             AND shortage.reservation_id = run.reservation_id
             AND shortage.id = run.pick_shortage_id
            WHERE run.tenant_id = NEW.tenant_id
              AND run.inventory_owner_id = NEW.inventory_owner_id
              AND run.facility_id = NEW.facility_id
              AND run.order_release_id = NEW.order_release_id
              AND run.order_id = NEW.order_id
              AND run.order_item_id = NEW.order_item_id
              AND run.reservation_id = NEW.reservation_id
              AND run.pick_shortage_id = NEW.pick_shortage_id
              AND run.id = NEW.pick_shortage_reallocation_run_id
        ) INTO recovery_matches;

        IF NOT recovery_matches THEN
            RAISE EXCEPTION 'shortage recovery snapshot does not match its reallocation run'
                USING ERRCODE = '23514';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: require_order_release_execution(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.require_order_release_execution() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    snapshot_count BIGINT;
    snapshot_qty BIGINT;
    task_count BIGINT;
    content_count BIGINT;
    final_order_matches BOOLEAN;
BEGIN
    SELECT COUNT(*), COALESCE(SUM(snapshot.planned_qty), 0)::BIGINT
    INTO snapshot_count, snapshot_qty
    FROM public.order_release_allocations snapshot
    WHERE snapshot.tenant_id = NEW.tenant_id
      AND snapshot.order_release_id = NEW.id
      AND snapshot.source_kind = 'initial';

    SELECT COUNT(*) INTO task_count
    FROM public.pick_tasks task
    INNER JOIN public.order_release_allocations snapshot
      ON snapshot.tenant_id = task.tenant_id
     AND snapshot.inventory_owner_id = task.inventory_owner_id
     AND snapshot.facility_id = task.facility_id
     AND snapshot.order_release_id = task.order_release_id
     AND snapshot.order_id = task.order_id
     AND snapshot.order_item_id = task.order_item_id
     AND snapshot.reservation_id = task.reservation_id
     AND snapshot.allocation_id = task.source_allocation_id
    WHERE task.tenant_id = NEW.tenant_id
      AND task.order_release_id = NEW.id
      AND snapshot.source_kind = 'initial';

    SELECT COUNT(*) INTO content_count
    FROM public.pick_task_contents content
    INNER JOIN public.order_release_allocations snapshot
      ON snapshot.tenant_id = content.tenant_id
     AND snapshot.inventory_owner_id = content.inventory_owner_id
     AND snapshot.facility_id = content.facility_id
     AND snapshot.order_release_id = content.order_release_id
     AND snapshot.order_id = content.order_id
     AND snapshot.order_item_id = content.order_item_id
     AND snapshot.reservation_id = content.reservation_id
     AND snapshot.allocation_id = content.source_allocation_id
    WHERE content.tenant_id = NEW.tenant_id
      AND content.order_release_id = NEW.id
      AND snapshot.source_kind = 'initial';

    SELECT EXISTS (
        SELECT 1 FROM public.orders customer_order
        WHERE customer_order.tenant_id = NEW.tenant_id
          AND customer_order.inventory_owner_id = NEW.inventory_owner_id
          AND customer_order.id = NEW.order_id
          AND customer_order.deleted IS NULL
          AND customer_order.status = 'processing'
          AND customer_order.revision = NEW.resulting_revision
    ) INTO final_order_matches;

    IF snapshot_count <> NEW.allocation_count
       OR snapshot_qty <> NEW.released_qty
       OR task_count <> NEW.pick_task_count
       OR content_count <> NEW.pick_task_count
       OR NOT final_order_matches
    THEN
        RAISE EXCEPTION 'order release execution snapshot is incomplete'
            USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: validate_pick_task(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_pick_task() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    task_matches BOOLEAN;
BEGIN
    SELECT EXISTS (
        SELECT 1
        FROM public.order_releases release
        INNER JOIN public.order_release_allocations snapshot
            ON snapshot.tenant_id = release.tenant_id
           AND snapshot.inventory_owner_id = release.inventory_owner_id
           AND snapshot.facility_id = release.facility_id
           AND snapshot.order_release_id = release.id
           AND snapshot.order_id = release.order_id
        WHERE release.tenant_id = NEW.tenant_id
          AND release.inventory_owner_id = NEW.inventory_owner_id
          AND release.facility_id = NEW.facility_id
          AND release.id = NEW.order_release_id
          AND release.order_id = NEW.order_id
          AND release.destination_location_id = NEW.destination_location_id
          AND snapshot.order_item_id = NEW.order_item_id
          AND snapshot.reservation_id = NEW.reservation_id
          AND snapshot.allocation_id = NEW.source_allocation_id
    ) INTO task_matches;

    IF NOT task_matches
       OR NEW.status <> 'open'
       OR NEW.assigned_user_id IS NOT NULL
       OR NEW.claimed_at IS NOT NULL
       OR NEW.lease_expires_at IS NOT NULL
       OR NEW.completed_at IS NOT NULL
    THEN
        RAISE EXCEPTION 'pick task does not match its release allocation'
            USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: validate_pick_task_content(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_pick_task_content() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    content_matches BOOLEAN;
BEGIN
    SELECT EXISTS (
        SELECT 1
        FROM public.pick_tasks task
        INNER JOIN public.order_release_allocations snapshot
            ON snapshot.tenant_id = task.tenant_id
           AND snapshot.inventory_owner_id = task.inventory_owner_id
           AND snapshot.facility_id = task.facility_id
           AND snapshot.order_release_id = task.order_release_id
           AND snapshot.order_id = task.order_id
           AND snapshot.order_item_id = task.order_item_id
           AND snapshot.reservation_id = task.reservation_id
           AND snapshot.allocation_id = task.source_allocation_id
        WHERE task.tenant_id = NEW.tenant_id
          AND task.inventory_owner_id = NEW.inventory_owner_id
          AND task.facility_id = NEW.facility_id
          AND task.id = NEW.task_id
          AND task.order_release_id = NEW.order_release_id
          AND task.order_id = NEW.order_id
          AND task.order_item_id = NEW.order_item_id
          AND task.reservation_id = NEW.reservation_id
          AND task.source_allocation_id = NEW.source_allocation_id
          AND task.status = 'open'
          AND snapshot.inventory_balance_id = NEW.source_inventory_balance_id
          AND snapshot.source_location_id = NEW.source_location_id
          AND snapshot.source_license_plate_id IS NOT DISTINCT FROM NEW.source_license_plate_id
          AND snapshot.item_batch_id = NEW.item_batch_id
          AND snapshot.item_id = NEW.item_id
          AND snapshot.uom = NEW.uom
          AND snapshot.inventory_status = NEW.inventory_status
          AND snapshot.planned_qty = NEW.planned_qty
          AND snapshot.travel_sequence = NEW.travel_sequence
    ) INTO content_matches;

    IF NOT content_matches
       OR NEW.state <> 'pending'
       OR NEW.completed_at IS NOT NULL
    THEN
        RAISE EXCEPTION 'pick content does not match its task and release snapshot'
            USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: validate_pick_confirmation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_pick_confirmation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    content_row RECORD;
    task_row RECORD;
    source_allocation_row RECORD;
    destination_allocation_row RECORD;
    transaction_row RECORD;
    entry_count BIGINT;
    entry_net BIGINT;
    source_entry_count BIGINT;
    destination_entry_count BIGINT;
BEGIN
    IF EXISTS (
        SELECT 1
        FROM public.pick_confirmations earlier
        WHERE earlier.tenant_id = NEW.tenant_id
          AND earlier.inventory_owner_id = NEW.inventory_owner_id
          AND (
              earlier.pick_task_content_id = NEW.pick_task_content_id
              OR earlier.source_inventory_allocation_id =
                 NEW.source_inventory_allocation_id
          )
          AND NOT EXISTS (
              SELECT 1 FROM public.pick_reversals reversal
              WHERE reversal.tenant_id = earlier.tenant_id
                AND reversal.inventory_owner_id = earlier.inventory_owner_id
                AND reversal.pick_confirmation_id = earlier.id
          )
    ) THEN
        RAISE EXCEPTION 'pick content or source allocation already has an active confirmation'
            USING ERRCODE = '55000';
    END IF;

    SELECT content.inventory_owner_id, content.facility_id, content.task_id,
           content.order_release_id, content.order_id, content.order_item_id,
           content.reservation_id, content.source_allocation_id,
           content.source_inventory_balance_id, content.source_location_id,
           content.source_license_plate_id, content.item_batch_id,
           content.item_id, content.uom, content.inventory_status,
           content.planned_qty, content.state
    INTO content_row
    FROM public.pick_task_contents content
    WHERE content.tenant_id = NEW.tenant_id
      AND content.id = NEW.pick_task_content_id
    FOR UPDATE;

    SELECT task.status, task.assigned_user_id, task.claimed_at,
           task.lease_expires_at, task.destination_location_id
    INTO task_row
    FROM public.pick_tasks task
    WHERE task.tenant_id = NEW.tenant_id
      AND task.id = NEW.task_id
    FOR UPDATE;

    IF content_row.task_id IS NULL OR task_row.status IS NULL
       OR content_row.state <> 'pending'
       OR task_row.status <> 'in_progress'
       OR task_row.assigned_user_id IS DISTINCT FROM NEW.confirmed_by_user_id
       OR NEW.confirmed_at < task_row.claimed_at
       OR task_row.lease_expires_at <= NEW.confirmed_at
       OR task_row.destination_location_id IS DISTINCT FROM NEW.destination_location_id
    THEN
        RAISE EXCEPTION 'pick confirmation requires the current active claim'
            USING ERRCODE = '55000';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.locations location
        WHERE location.tenant_id = NEW.tenant_id
          AND location.facility_id = NEW.facility_id
          AND location.id = NEW.destination_location_id
          AND location.deleted IS NULL
          AND location.active
          AND NOT location.pickable
          AND location.barcode IS NOT NULL
          AND location.barcode = btrim(location.barcode)
          AND location.barcode <> ''
          AND lower(location.type) IN ('staging', 'packing')
    ) THEN
        RAISE EXCEPTION 'pick confirmation destination must remain an active scannable staging or packing location'
            USING ERRCODE = '55000';
    END IF;

    IF NEW.inventory_owner_id IS DISTINCT FROM content_row.inventory_owner_id
       OR NEW.facility_id IS DISTINCT FROM content_row.facility_id
       OR NEW.task_id IS DISTINCT FROM content_row.task_id
       OR NEW.order_release_id IS DISTINCT FROM content_row.order_release_id
       OR NEW.order_id IS DISTINCT FROM content_row.order_id
       OR NEW.order_item_id IS DISTINCT FROM content_row.order_item_id
       OR NEW.reservation_id IS DISTINCT FROM content_row.reservation_id
       OR NEW.source_inventory_allocation_id IS DISTINCT FROM content_row.source_allocation_id
       OR NEW.source_inventory_balance_id IS DISTINCT FROM content_row.source_inventory_balance_id
       OR NEW.source_location_id IS DISTINCT FROM content_row.source_location_id
       OR NEW.source_license_plate_id IS DISTINCT FROM content_row.source_license_plate_id
       OR NEW.item_batch_id IS DISTINCT FROM content_row.item_batch_id
       OR NEW.item_id IS DISTINCT FROM content_row.item_id
       OR NEW.uom IS DISTINCT FROM content_row.uom
       OR NEW.inventory_status IS DISTINCT FROM content_row.inventory_status
       OR NEW.picked_qty > content_row.planned_qty
    THEN
        RAISE EXCEPTION 'pick confirmation does not match its immutable content'
            USING ERRCODE = '23514';
    END IF;

    SELECT allocation.reservation_id, allocation.inventory_balance_id,
           allocation.facility_id, allocation.location_id,
           allocation.license_plate_id, allocation.item_batch_id,
           allocation.item_id, allocation.uom, allocation.inventory_status,
           allocation.qty, allocation.status, allocation.modified,
           allocation.deleted, allocation.execution_stage
    INTO source_allocation_row
    FROM public.inventory_allocations allocation
    WHERE allocation.tenant_id = NEW.tenant_id
      AND allocation.inventory_owner_id = NEW.inventory_owner_id
      AND allocation.id = NEW.source_inventory_allocation_id
    FOR SHARE;

    SELECT allocation.reservation_id, allocation.inventory_balance_id,
           allocation.facility_id, allocation.location_id,
           allocation.license_plate_id, allocation.item_batch_id,
           allocation.item_id, allocation.uom, allocation.inventory_status,
           allocation.qty, allocation.status, allocation.created,
           allocation.modified, allocation.deleted, allocation.created_by,
           allocation.execution_stage
    INTO destination_allocation_row
    FROM public.inventory_allocations allocation
    WHERE allocation.tenant_id = NEW.tenant_id
      AND allocation.inventory_owner_id = NEW.inventory_owner_id
      AND allocation.id = NEW.destination_inventory_allocation_id
    FOR SHARE;

    IF source_allocation_row.reservation_id IS NULL
       OR source_allocation_row.reservation_id IS DISTINCT FROM NEW.reservation_id
       OR source_allocation_row.inventory_balance_id IS DISTINCT FROM NEW.source_inventory_balance_id
       OR source_allocation_row.facility_id IS DISTINCT FROM NEW.facility_id
       OR source_allocation_row.location_id IS DISTINCT FROM NEW.source_location_id
       OR source_allocation_row.license_plate_id IS DISTINCT FROM NEW.source_license_plate_id
       OR source_allocation_row.item_batch_id IS DISTINCT FROM NEW.item_batch_id
       OR source_allocation_row.item_id IS DISTINCT FROM NEW.item_id
       OR source_allocation_row.uom IS DISTINCT FROM NEW.uom
       OR source_allocation_row.inventory_status IS DISTINCT FROM NEW.inventory_status
       OR source_allocation_row.qty IS DISTINCT FROM content_row.planned_qty
       OR source_allocation_row.execution_stage <> 'pick_source'
       OR (
           (NEW.picked_qty = content_row.planned_qty
            AND source_allocation_row.status <> 'fulfilled')
           OR (NEW.picked_qty < content_row.planned_qty
               AND source_allocation_row.status <> 'shorted')
       )
       OR source_allocation_row.modified IS DISTINCT FROM NEW.confirmed_at
       OR source_allocation_row.deleted IS DISTINCT FROM NEW.confirmed_at
    THEN
        RAISE EXCEPTION 'source allocation was not fulfilled by this pick'
            USING ERRCODE = '23514';
    END IF;

    IF destination_allocation_row.reservation_id IS NULL
       OR destination_allocation_row.reservation_id IS DISTINCT FROM NEW.reservation_id
       OR destination_allocation_row.inventory_balance_id IS DISTINCT FROM NEW.destination_inventory_balance_id
       OR destination_allocation_row.facility_id IS DISTINCT FROM NEW.facility_id
       OR destination_allocation_row.location_id IS DISTINCT FROM NEW.destination_location_id
       OR destination_allocation_row.license_plate_id IS DISTINCT FROM NEW.destination_license_plate_id
       OR destination_allocation_row.item_batch_id IS DISTINCT FROM NEW.item_batch_id
       OR destination_allocation_row.item_id IS DISTINCT FROM NEW.item_id
       OR destination_allocation_row.uom IS DISTINCT FROM NEW.uom
       OR destination_allocation_row.inventory_status IS DISTINCT FROM NEW.inventory_status
       OR destination_allocation_row.qty IS DISTINCT FROM NEW.picked_qty
       OR destination_allocation_row.status <> 'allocated'
       OR destination_allocation_row.execution_stage <> 'staged'
       OR destination_allocation_row.created IS DISTINCT FROM NEW.confirmed_at
       OR destination_allocation_row.modified IS NOT NULL
       OR destination_allocation_row.deleted IS NOT NULL
       OR destination_allocation_row.created_by IS DISTINCT FROM NEW.confirmed_by_user_id
    THEN
        RAISE EXCEPTION 'destination allocation does not protect picked inventory'
            USING ERRCODE = '23514';
    END IF;

    SELECT transaction.actor_user_id, transaction.transaction_type,
           transaction.reference_type, transaction.reference_id
    INTO transaction_row
    FROM public.inventory_transactions transaction
    WHERE transaction.tenant_id = NEW.tenant_id
      AND transaction.inventory_owner_id = NEW.inventory_owner_id
      AND transaction.id = NEW.inventory_transaction_id;

    IF transaction_row.transaction_type IS NULL
       OR transaction_row.actor_user_id IS DISTINCT FROM NEW.confirmed_by_user_id
       OR transaction_row.transaction_type <> 'move'
       OR transaction_row.reference_type <> 'pick_task_content'
       OR transaction_row.reference_id IS DISTINCT FROM NEW.pick_task_content_id
    THEN
        RAISE EXCEPTION 'pick inventory transaction does not match confirmation'
            USING ERRCODE = '23514';
    END IF;

    SELECT COUNT(*), COALESCE(SUM(entry.quantity_delta), 0)::BIGINT,
           COUNT(*) FILTER (WHERE entry.facility_id = NEW.facility_id
                              AND entry.item_batch_id = NEW.item_batch_id
                              AND entry.item_id = NEW.item_id
                              AND entry.uom = NEW.uom
                              AND entry.status = NEW.inventory_status
                              AND entry.location_id = NEW.source_location_id
                              AND entry.license_plate_id IS NOT DISTINCT FROM NEW.source_license_plate_id
                              AND entry.quantity_delta = -NEW.picked_qty),
           COUNT(*) FILTER (WHERE entry.facility_id = NEW.facility_id
                              AND entry.item_batch_id = NEW.item_batch_id
                              AND entry.item_id = NEW.item_id
                              AND entry.uom = NEW.uom
                              AND entry.status = NEW.inventory_status
                              AND entry.location_id = NEW.destination_location_id
                              AND entry.license_plate_id = NEW.destination_license_plate_id
                              AND entry.quantity_delta = NEW.picked_qty)
    INTO entry_count, entry_net, source_entry_count, destination_entry_count
    FROM public.inventory_entries entry
    WHERE entry.tenant_id = NEW.tenant_id
      AND entry.inventory_owner_id = NEW.inventory_owner_id
      AND entry.transaction_id = NEW.inventory_transaction_id;

    IF entry_count <> 2 OR entry_net <> 0
       OR source_entry_count <> 1 OR destination_entry_count <> 1
    THEN
        RAISE EXCEPTION 'pick inventory entries do not conserve confirmed quantity'
            USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: require_pick_confirmation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.require_pick_confirmation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
    IF NEW.state = 'completed'
       AND NOT EXISTS (
           SELECT 1 FROM public.pick_confirmations confirmation
           WHERE confirmation.tenant_id = NEW.tenant_id
             AND confirmation.pick_task_content_id = NEW.id
             AND confirmation.confirmed_at = NEW.completed_at
       )
    THEN
        RAISE EXCEPTION 'completed pick content requires an immutable confirmation'
            USING ERRCODE = '23514';
    ELSIF NEW.state = 'shorted'
       AND NOT EXISTS (
           SELECT 1 FROM public.pick_shortages shortage
           WHERE shortage.tenant_id = NEW.tenant_id
             AND shortage.inventory_owner_id = NEW.inventory_owner_id
             AND shortage.facility_id = NEW.facility_id
             AND shortage.task_id = NEW.task_id
             AND shortage.pick_task_content_id = NEW.id
             AND shortage.reported_at = NEW.completed_at
       )
    THEN
        RAISE EXCEPTION 'shorted pick content requires an immutable shortage report'
            USING ERRCODE = '23514';
    ELSIF NEW.state = 'cancelled'
       AND NOT EXISTS (
           SELECT 1 FROM public.order_cancellations cancellation
           WHERE cancellation.tenant_id = NEW.tenant_id
             AND cancellation.inventory_owner_id = NEW.inventory_owner_id
             AND cancellation.order_id = NEW.order_id
             AND cancellation.previous_status = 'processing'
             AND cancellation.occurred_at = NEW.completed_at
       )
    THEN
        RAISE EXCEPTION 'cancelled pick content requires immutable order cancellation evidence'
            USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: require_completed_pick_content(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.require_completed_pick_content() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
    IF NEW.status = 'completed'
       AND NOT EXISTS (
           SELECT 1 FROM public.pick_task_contents content
           WHERE content.tenant_id = NEW.tenant_id
             AND content.task_id = NEW.id
             AND content.state = 'completed'
             AND content.completed_at = NEW.completed_at
       )
    THEN
        RAISE EXCEPTION 'completed pick task requires completed content'
            USING ERRCODE = '23514';
    ELSIF NEW.status = 'shorted'
       AND NOT EXISTS (
           SELECT 1 FROM public.pick_task_contents content
           WHERE content.tenant_id = NEW.tenant_id
             AND content.task_id = NEW.id
             AND content.state = 'shorted'
             AND content.completed_at = NEW.completed_at
       )
    THEN
        RAISE EXCEPTION 'shorted pick task requires shorted content'
            USING ERRCODE = '23514';
    ELSIF NEW.status = 'cancelled'
       AND (
           NOT EXISTS (
               SELECT 1 FROM public.pick_task_contents content
               WHERE content.tenant_id = NEW.tenant_id
                 AND content.task_id = NEW.id
                 AND content.state = 'cancelled'
                 AND content.completed_at = NEW.completed_at
           )
           OR NOT EXISTS (
               SELECT 1 FROM public.order_cancellations cancellation
               WHERE cancellation.tenant_id = NEW.tenant_id
                 AND cancellation.inventory_owner_id = NEW.inventory_owner_id
                 AND cancellation.order_id = NEW.order_id
                 AND cancellation.previous_status = 'processing'
                 AND cancellation.occurred_at = NEW.completed_at
           )
       )
    THEN
        RAISE EXCEPTION 'cancelled pick task requires content and order cancellation evidence'
            USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: guard_pick_shortage_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_pick_shortage_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'pick shortages are retained permanently'
            USING ERRCODE = '55000';
    END IF;

    IF NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
       OR NEW.inventory_owner_id IS DISTINCT FROM OLD.inventory_owner_id
       OR NEW.facility_id IS DISTINCT FROM OLD.facility_id
       OR NEW.order_release_id IS DISTINCT FROM OLD.order_release_id
       OR NEW.order_id IS DISTINCT FROM OLD.order_id
       OR NEW.order_item_id IS DISTINCT FROM OLD.order_item_id
       OR NEW.reservation_id IS DISTINCT FROM OLD.reservation_id
       OR NEW.task_id IS DISTINCT FROM OLD.task_id
       OR NEW.pick_task_content_id IS DISTINCT FROM OLD.pick_task_content_id
       OR NEW.source_inventory_allocation_id IS DISTINCT FROM OLD.source_inventory_allocation_id
       OR NEW.source_inventory_balance_id IS DISTINCT FROM OLD.source_inventory_balance_id
       OR NEW.source_location_id IS DISTINCT FROM OLD.source_location_id
       OR NEW.source_license_plate_id IS DISTINCT FROM OLD.source_license_plate_id
       OR NEW.destination_location_id IS DISTINCT FROM OLD.destination_location_id
       OR NEW.item_batch_id IS DISTINCT FROM OLD.item_batch_id
       OR NEW.item_id IS DISTINCT FROM OLD.item_id
       OR NEW.uom IS DISTINCT FROM OLD.uom
       OR NEW.inventory_status IS DISTINCT FROM OLD.inventory_status
       OR NEW.planned_qty IS DISTINCT FROM OLD.planned_qty
       OR NEW.picked_qty IS DISTINCT FROM OLD.picked_qty
       OR NEW.short_qty IS DISTINCT FROM OLD.short_qty
       OR NEW.reason_code IS DISTINCT FROM OLD.reason_code
       OR NEW.note IS DISTINCT FROM OLD.note
       OR NEW.observed_item_barcode IS DISTINCT FROM OLD.observed_item_barcode
       OR NEW.observed_lot IS DISTINCT FROM OLD.observed_lot
       OR NEW.observed_serial IS DISTINCT FROM OLD.observed_serial
       OR NEW.inventory_hold_id IS DISTINCT FROM OLD.inventory_hold_id
       OR NEW.pick_confirmation_id IS DISTINCT FROM OLD.pick_confirmation_id
       OR NEW.inventory_transaction_id IS DISTINCT FROM OLD.inventory_transaction_id
       OR NEW.destination_inventory_allocation_id IS DISTINCT FROM OLD.destination_inventory_allocation_id
       OR NEW.destination_inventory_balance_id IS DISTINCT FROM OLD.destination_inventory_balance_id
       OR NEW.destination_license_plate_id IS DISTINCT FROM OLD.destination_license_plate_id
       OR NEW.reported_by_user_id IS DISTINCT FROM OLD.reported_by_user_id
       OR NEW.reported_at IS DISTINCT FROM OLD.reported_at
       OR NEW.report_previous_order_revision IS DISTINCT FROM OLD.report_previous_order_revision
       OR NEW.report_resulting_order_revision IS DISTINCT FROM OLD.report_resulting_order_revision
    THEN
        RAISE EXCEPTION 'pick shortage report facts are immutable'
            USING ERRCODE = '55000';
    END IF;

    IF OLD.status = 'resolved' THEN
        RAISE EXCEPTION 'resolved pick shortages are immutable'
            USING ERRCODE = '55000';
    END IF;

    IF NEW.status = 'resolved'
       AND NEW.resolution IS NULL
       AND NEW.recovery_terminal_qty = NEW.short_qty
       AND NEW.reallocated_qty = NEW.short_qty
       AND NEW.remaining_to_allocate_qty = 0
       AND NEW.accepted_short_qty = 0
    THEN
        NEW.resolution := 'recovered';
    END IF;

    IF NEW.resolution IS DISTINCT FROM OLD.resolution
       OR NEW.accepted_short_qty IS DISTINCT FROM OLD.accepted_short_qty
    THEN
        IF NOT (
            OLD.status = 'awaiting_inventory'
            AND OLD.resolution IS NULL
            AND OLD.accepted_short_qty = 0
            AND NEW.status = 'resolved'
            AND NEW.resolution = 'short_ship'
            AND NEW.accepted_short_qty = OLD.remaining_to_allocate_qty
            AND NEW.reallocated_qty = OLD.reallocated_qty
            AND NEW.recovery_terminal_qty = OLD.recovery_terminal_qty
            AND NEW.remaining_to_allocate_qty = OLD.remaining_to_allocate_qty
        ) AND NOT (
            NEW.status = 'resolved'
            AND NEW.resolution = 'recovered'
            AND NEW.accepted_short_qty = 0
            AND NEW.reallocated_qty = NEW.short_qty
            AND NEW.recovery_terminal_qty = NEW.short_qty
            AND NEW.remaining_to_allocate_qty = 0
        )
        THEN
            RAISE EXCEPTION 'invalid pick shortage resolution transition'
                USING ERRCODE = '55000';
        END IF;
    END IF;

    IF NEW.revision <> OLD.revision + 1
       OR NEW.modified_at <= OLD.modified_at
       OR NEW.reallocated_qty < OLD.reallocated_qty
       OR NEW.recovery_terminal_qty < OLD.recovery_terminal_qty
       OR NEW.remaining_to_allocate_qty > OLD.remaining_to_allocate_qty
    THEN
        RAISE EXCEPTION 'invalid pick shortage lifecycle revision'
            USING ERRCODE = '55000';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: reject_pick_short_ship_disposition_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_pick_short_ship_disposition_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'pick short-ship dispositions are immutable'
        USING ERRCODE = '55000';
END;
$$;


--
-- Name: validate_pick_short_ship_disposition(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_pick_short_ship_disposition() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    shortage_row public.pick_shortages%ROWTYPE;
    order_status TEXT;
    order_revision BIGINT;
    original_order_qty BIGINT;
    original_line_qty BIGINT;
    reservation_qty BIGINT;
    previously_accepted_order_qty BIGINT;
    previously_accepted_line_qty BIGINT;
    previously_accepted_reservation_qty BIGINT;
BEGIN
    SELECT order_header.status, order_header.revision
    INTO order_status, order_revision
    FROM public.orders order_header
    WHERE order_header.tenant_id = NEW.tenant_id
      AND order_header.inventory_owner_id = NEW.inventory_owner_id
      AND order_header.id = NEW.order_id
      AND order_header.deleted IS NULL
    FOR UPDATE OF order_header;

    IF order_status IS DISTINCT FROM 'processing'
       OR order_revision NOT IN (
           NEW.expected_order_revision,
           NEW.resulting_order_revision
       )
    THEN
        RAISE EXCEPTION 'short-ship disposition order revision is stale or not processing'
            USING ERRCODE = '23514';
    END IF;

    SELECT * INTO shortage_row
    FROM public.pick_shortages shortage
    WHERE shortage.tenant_id = NEW.tenant_id
      AND shortage.inventory_owner_id = NEW.inventory_owner_id
      AND shortage.facility_id = NEW.facility_id
      AND shortage.order_release_id = NEW.order_release_id
      AND shortage.order_id = NEW.order_id
      AND shortage.order_item_id = NEW.order_item_id
      AND shortage.reservation_id = NEW.reservation_id
      AND shortage.id = NEW.pick_shortage_id
    FOR UPDATE OF shortage;

    IF NOT FOUND
       OR shortage_row.revision NOT IN (
           NEW.expected_shortage_revision,
           NEW.resulting_shortage_revision
       )
       OR shortage_row.reallocated_qty <> shortage_row.recovery_terminal_qty
       OR shortage_row.remaining_to_allocate_qty <= 0
       OR shortage_row.accepted_short_qty NOT IN (0, NEW.accepted_short_qty)
       OR shortage_row.remaining_to_allocate_qty <> NEW.accepted_short_qty
       OR NOT (
           (shortage_row.revision = NEW.expected_shortage_revision
            AND shortage_row.status = 'awaiting_inventory'
            AND shortage_row.resolution IS NULL
            AND shortage_row.accepted_short_qty = 0
            AND shortage_row.resolved_by_user_id IS NULL
            AND shortage_row.resolved_at IS NULL)
           OR
           (shortage_row.revision = NEW.resulting_shortage_revision
            AND shortage_row.status = 'resolved'
            AND shortage_row.resolution = 'short_ship'
            AND shortage_row.accepted_short_qty = NEW.accepted_short_qty
            AND shortage_row.resolved_by_user_id = NEW.disposed_by_user_id
            AND shortage_row.resolved_at = NEW.disposed_at)
       )
       OR NOT EXISTS (
           SELECT 1
           FROM public.inventory_holds discrepancy_hold
           WHERE discrepancy_hold.tenant_id = shortage_row.tenant_id
             AND discrepancy_hold.inventory_owner_id = shortage_row.inventory_owner_id
             AND discrepancy_hold.facility_id = shortage_row.facility_id
             AND discrepancy_hold.id = shortage_row.inventory_hold_id
             AND discrepancy_hold.qty = shortage_row.short_qty
             AND discrepancy_hold.reason_code = 'inventory_discrepancy'
             AND discrepancy_hold.reference_type = 'pick_shortage_source'
             AND discrepancy_hold.reference_id = shortage_row.pick_task_content_id
             AND discrepancy_hold.status = 'active'
             AND discrepancy_hold.deleted IS NULL
       )
    THEN
        RAISE EXCEPTION 'short-ship disposition does not match an unresolved shortage and active discrepancy hold'
            USING ERRCODE = '23514';
    END IF;

    SELECT COALESCE(SUM(order_line.qty), 0)::BIGINT
    INTO original_order_qty
    FROM public.order_items order_line
    WHERE order_line.tenant_id = NEW.tenant_id
      AND order_line.inventory_owner_id = NEW.inventory_owner_id
      AND order_line.order_id = NEW.order_id
      AND order_line.deleted IS NULL;

    SELECT order_line.qty, reservation.qty
    INTO original_line_qty, reservation_qty
    FROM public.order_items order_line
    INNER JOIN public.inventory_reservations reservation
      ON reservation.tenant_id = order_line.tenant_id
     AND reservation.inventory_owner_id = order_line.inventory_owner_id
     AND reservation.order_id = order_line.order_id
     AND reservation.order_item_id = order_line.id
    WHERE order_line.tenant_id = NEW.tenant_id
      AND order_line.inventory_owner_id = NEW.inventory_owner_id
      AND order_line.order_id = NEW.order_id
      AND order_line.id = NEW.order_item_id
      AND order_line.deleted IS NULL
      AND reservation.facility_id = NEW.facility_id
      AND reservation.id = NEW.reservation_id
      AND reservation.status = 'active'
      AND reservation.deleted IS NULL;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'short-ship disposition requires active scoped demand'
            USING ERRCODE = '23514';
    END IF;

    SELECT COALESCE(SUM(disposition.accepted_short_qty), 0)::BIGINT,
           COALESCE(SUM(disposition.accepted_short_qty) FILTER (
               WHERE disposition.order_item_id = NEW.order_item_id
           ), 0)::BIGINT,
           COALESCE(SUM(disposition.accepted_short_qty) FILTER (
               WHERE disposition.reservation_id = NEW.reservation_id
           ), 0)::BIGINT
    INTO previously_accepted_order_qty,
         previously_accepted_line_qty,
         previously_accepted_reservation_qty
    FROM public.pick_short_ship_dispositions disposition
    WHERE disposition.tenant_id = NEW.tenant_id
      AND disposition.inventory_owner_id = NEW.inventory_owner_id
      AND disposition.order_id = NEW.order_id;

    IF original_order_qty - previously_accepted_order_qty - NEW.accepted_short_qty <= 0 THEN
        RAISE EXCEPTION 'short-ship disposition cannot reduce order effective demand to zero'
            USING ERRCODE = '55000';
    END IF;

    IF original_line_qty - previously_accepted_line_qty - NEW.accepted_short_qty < 0
       OR reservation_qty - previously_accepted_reservation_qty - NEW.accepted_short_qty < 0
    THEN
        RAISE EXCEPTION 'accepted short quantity exceeds original line or reservation demand'
            USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: reject_pick_shortage_reallocation_run_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_pick_shortage_reallocation_run_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'pick shortage reallocation runs are immutable'
        USING ERRCODE = '55000';
END;
$$;


--
-- Name: validate_pick_shortage(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_pick_shortage() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    report_matches BOOLEAN;
    movement_matches BOOLEAN;
BEGIN
    IF NEW.revision <> 1
       OR NEW.modified_at IS DISTINCT FROM NEW.reported_at
       OR NEW.status <> 'awaiting_inventory'
       OR NEW.resolution IS NOT NULL
       OR NEW.accepted_short_qty <> 0
       OR NEW.reallocated_qty <> 0
       OR NEW.recovery_terminal_qty <> 0
       OR NEW.remaining_to_allocate_qty <> NEW.short_qty
       OR NEW.resolved_by_user_id IS NOT NULL
       OR NEW.resolved_at IS NOT NULL
    THEN
        RAISE EXCEPTION 'new pick shortage must begin awaiting inventory at revision one'
            USING ERRCODE = '23514';
    END IF;

    SELECT EXISTS (
        SELECT 1
        FROM public.pick_tasks task
        INNER JOIN public.pick_task_contents content
          ON content.tenant_id = task.tenant_id
         AND content.inventory_owner_id = task.inventory_owner_id
         AND content.facility_id = task.facility_id
         AND content.task_id = task.id
        INNER JOIN public.order_release_allocations snapshot
          ON snapshot.tenant_id = content.tenant_id
         AND snapshot.inventory_owner_id = content.inventory_owner_id
         AND snapshot.facility_id = content.facility_id
         AND snapshot.order_release_id = content.order_release_id
         AND snapshot.order_id = content.order_id
         AND snapshot.order_item_id = content.order_item_id
         AND snapshot.reservation_id = content.reservation_id
         AND snapshot.allocation_id = content.source_allocation_id
        INNER JOIN public.inventory_allocations source_allocation
          ON source_allocation.tenant_id = content.tenant_id
         AND source_allocation.inventory_owner_id = content.inventory_owner_id
         AND source_allocation.facility_id = content.facility_id
         AND source_allocation.id = content.source_allocation_id
        INNER JOIN public.inventory_holds discrepancy_hold
          ON discrepancy_hold.tenant_id = content.tenant_id
         AND discrepancy_hold.inventory_owner_id = content.inventory_owner_id
         AND discrepancy_hold.id = NEW.inventory_hold_id
        INNER JOIN public.orders order_header
          ON order_header.tenant_id = content.tenant_id
         AND order_header.inventory_owner_id = content.inventory_owner_id
         AND order_header.id = content.order_id
        WHERE task.tenant_id = NEW.tenant_id
          AND task.inventory_owner_id = NEW.inventory_owner_id
          AND task.facility_id = NEW.facility_id
          AND task.id = NEW.task_id
          AND task.order_release_id = NEW.order_release_id
          AND task.order_id = NEW.order_id
          AND task.order_item_id = NEW.order_item_id
          AND task.reservation_id = NEW.reservation_id
          AND task.source_allocation_id = NEW.source_inventory_allocation_id
          AND task.destination_location_id = NEW.destination_location_id
          AND task.status = 'in_progress'
          AND task.assigned_user_id = NEW.reported_by_user_id
          AND task.claimed_at <= NEW.reported_at
          AND task.lease_expires_at > NEW.reported_at
          AND content.id = NEW.pick_task_content_id
          AND content.state = 'pending'
          AND content.source_inventory_balance_id = NEW.source_inventory_balance_id
          AND content.source_location_id = NEW.source_location_id
          AND content.source_license_plate_id IS NOT DISTINCT FROM NEW.source_license_plate_id
          AND content.item_batch_id = NEW.item_batch_id
          AND content.item_id = NEW.item_id
          AND content.uom = NEW.uom
          AND content.inventory_status = NEW.inventory_status
          AND content.planned_qty = NEW.planned_qty
          AND source_allocation.inventory_balance_id = NEW.source_inventory_balance_id
          AND source_allocation.location_id = NEW.source_location_id
          AND source_allocation.license_plate_id IS NOT DISTINCT FROM NEW.source_license_plate_id
          AND source_allocation.item_batch_id = NEW.item_batch_id
          AND source_allocation.item_id = NEW.item_id
          AND source_allocation.uom = NEW.uom
          AND source_allocation.inventory_status = NEW.inventory_status
          AND source_allocation.qty = NEW.planned_qty
          AND source_allocation.status = 'shorted'
          AND source_allocation.execution_stage = 'pick_source'
          AND source_allocation.modified = NEW.reported_at
          AND source_allocation.deleted = NEW.reported_at
          AND discrepancy_hold.facility_id = NEW.facility_id
          AND discrepancy_hold.inventory_balance_id = NEW.source_inventory_balance_id
          AND discrepancy_hold.location_id = NEW.source_location_id
          AND discrepancy_hold.license_plate_id IS NOT DISTINCT FROM NEW.source_license_plate_id
          AND discrepancy_hold.item_batch_id = NEW.item_batch_id
          AND discrepancy_hold.item_id = NEW.item_id
          AND discrepancy_hold.uom = NEW.uom
          AND discrepancy_hold.inventory_status = NEW.inventory_status
          AND discrepancy_hold.qty = NEW.short_qty
          AND discrepancy_hold.reason_code = 'inventory_discrepancy'
          AND discrepancy_hold.reference_type = 'pick_shortage_source'
          AND discrepancy_hold.reference_id = NEW.pick_task_content_id
          AND discrepancy_hold.status = 'active'
          AND discrepancy_hold.created_by = NEW.reported_by_user_id
          AND discrepancy_hold.created = NEW.reported_at
          AND order_header.deleted IS NULL
          AND order_header.status = 'processing'
          AND order_header.revision = NEW.report_previous_order_revision
    ) INTO report_matches;

    IF NOT report_matches THEN
        RAISE EXCEPTION 'pick shortage does not match the active claim, source, hold, or order revision'
            USING ERRCODE = '23514';
    END IF;

    IF NEW.picked_qty > 0 THEN
        SELECT EXISTS (
            SELECT 1
            FROM public.pick_confirmations confirmation
            INNER JOIN public.inventory_allocations destination_allocation
              ON destination_allocation.tenant_id = confirmation.tenant_id
             AND destination_allocation.inventory_owner_id = confirmation.inventory_owner_id
             AND destination_allocation.facility_id = confirmation.facility_id
             AND destination_allocation.id = confirmation.destination_inventory_allocation_id
            WHERE confirmation.tenant_id = NEW.tenant_id
              AND confirmation.inventory_owner_id = NEW.inventory_owner_id
              AND confirmation.facility_id = NEW.facility_id
              AND confirmation.id = NEW.pick_confirmation_id
              AND confirmation.task_id = NEW.task_id
              AND confirmation.pick_task_content_id = NEW.pick_task_content_id
              AND confirmation.order_release_id = NEW.order_release_id
              AND confirmation.order_id = NEW.order_id
              AND confirmation.order_item_id = NEW.order_item_id
              AND confirmation.reservation_id = NEW.reservation_id
              AND confirmation.source_inventory_allocation_id = NEW.source_inventory_allocation_id
              AND confirmation.destination_inventory_allocation_id = NEW.destination_inventory_allocation_id
              AND confirmation.source_inventory_balance_id = NEW.source_inventory_balance_id
              AND confirmation.destination_inventory_balance_id = NEW.destination_inventory_balance_id
              AND confirmation.source_location_id = NEW.source_location_id
              AND confirmation.destination_location_id = NEW.destination_location_id
              AND confirmation.source_license_plate_id IS NOT DISTINCT FROM NEW.source_license_plate_id
              AND confirmation.destination_license_plate_id = NEW.destination_license_plate_id
              AND confirmation.item_batch_id = NEW.item_batch_id
              AND confirmation.item_id = NEW.item_id
              AND confirmation.uom = NEW.uom
              AND confirmation.inventory_status = NEW.inventory_status
              AND confirmation.inventory_transaction_id = NEW.inventory_transaction_id
              AND confirmation.picked_qty = NEW.picked_qty
              AND confirmation.confirmed_by_user_id = NEW.reported_by_user_id
              AND confirmation.confirmed_at = NEW.reported_at
              AND destination_allocation.status = 'allocated'
              AND destination_allocation.execution_stage = 'staged'
              AND destination_allocation.deleted IS NULL
              AND destination_allocation.qty = NEW.picked_qty
        ) INTO movement_matches;

        IF NOT movement_matches THEN
            RAISE EXCEPTION 'partial pick shortage does not match its immutable pick movement'
                USING ERRCODE = '23514';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: validate_pick_shortage_reallocation_run(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_pick_shortage_reallocation_run() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM public.pick_shortages shortage
        INNER JOIN public.order_releases release
          ON release.tenant_id = shortage.tenant_id
         AND release.inventory_owner_id = shortage.inventory_owner_id
         AND release.facility_id = shortage.facility_id
         AND release.id = shortage.order_release_id
         AND release.order_id = shortage.order_id
        INNER JOIN public.orders order_header
          ON order_header.tenant_id = shortage.tenant_id
         AND order_header.inventory_owner_id = shortage.inventory_owner_id
         AND order_header.id = shortage.order_id
        WHERE shortage.tenant_id = NEW.tenant_id
          AND shortage.inventory_owner_id = NEW.inventory_owner_id
          AND shortage.facility_id = NEW.facility_id
          AND shortage.order_release_id = NEW.order_release_id
          AND shortage.order_id = NEW.order_id
          AND shortage.order_item_id = NEW.order_item_id
          AND shortage.reservation_id = NEW.reservation_id
          AND shortage.id = NEW.pick_shortage_id
          AND shortage.status <> 'resolved'
          AND shortage.revision = NEW.expected_shortage_revision
          AND shortage.remaining_to_allocate_qty = NEW.requested_qty
          AND order_header.deleted IS NULL
          AND order_header.status = 'processing'
          AND order_header.revision = NEW.expected_order_revision
    ) THEN
        RAISE EXCEPTION 'pick shortage reallocation run is stale or outside the shortage scope'
            USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: require_pick_confirmation_execution(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.require_pick_confirmation_execution() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    planned_qty BIGINT;
    content_state TEXT;
    content_completed_at TIMESTAMPTZ;
    task_status TEXT;
    task_completed_at TIMESTAMPTZ;
BEGIN
    SELECT content.planned_qty, content.state, content.completed_at,
           task.status, task.completed_at
    INTO planned_qty, content_state, content_completed_at,
         task_status, task_completed_at
    FROM public.pick_task_contents content
    INNER JOIN public.pick_tasks task
      ON task.tenant_id = content.tenant_id
     AND task.inventory_owner_id = content.inventory_owner_id
     AND task.facility_id = content.facility_id
     AND task.id = content.task_id
    WHERE content.tenant_id = NEW.tenant_id
      AND content.inventory_owner_id = NEW.inventory_owner_id
      AND content.id = NEW.pick_task_content_id;

    IF NEW.picked_qty = planned_qty THEN
        IF content_state <> 'completed'
           OR task_status <> 'completed'
           OR content_completed_at IS DISTINCT FROM NEW.confirmed_at
           OR task_completed_at IS DISTINCT FROM NEW.confirmed_at
        THEN
            RAISE EXCEPTION 'full pick confirmation requires completed task and content'
                USING ERRCODE = '23514';
        END IF;
    ELSIF NEW.picked_qty < planned_qty THEN
        IF content_state <> 'shorted'
           OR task_status <> 'shorted'
           OR content_completed_at IS DISTINCT FROM NEW.confirmed_at
           OR task_completed_at IS DISTINCT FROM NEW.confirmed_at
           OR NOT EXISTS (
               SELECT 1 FROM public.pick_shortages shortage
               WHERE shortage.tenant_id = NEW.tenant_id
                 AND shortage.inventory_owner_id = NEW.inventory_owner_id
                 AND shortage.pick_confirmation_id = NEW.id
                 AND shortage.pick_task_content_id = NEW.pick_task_content_id
                 AND shortage.reported_at = NEW.confirmed_at
           )
        THEN
            RAISE EXCEPTION 'partial pick confirmation requires a terminal shortage report'
                USING ERRCODE = '23514';
        END IF;
    ELSE
        RAISE EXCEPTION 'pick confirmation exceeds planned quantity'
            USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: require_pick_shortage_consistency(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.require_pick_shortage_consistency() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    shortage_id BIGINT;
    shortage_row RECORD;
    disposition_count BIGINT;
    disposition_accepted_short_qty BIGINT;
    disposition_resulting_shortage_revision BIGINT;
    disposition_resulting_order_revision BIGINT;
    disposition_disposed_by_user_id BIGINT;
    disposition_disposed_at TIMESTAMPTZ;
    reallocated_qty BIGINT;
    recovery_terminal_qty BIGINT;
    expected_status TEXT;
    expected_resolution TEXT;
    expected_accepted_short_qty BIGINT;
    order_revision BIGINT;
BEGIN
    IF TG_TABLE_NAME = 'pick_shortages' THEN
        shortage_id := NEW.id;
    ELSIF TG_TABLE_NAME = 'pick_short_ship_dispositions' THEN
        shortage_id := NEW.pick_shortage_id;
    ELSIF TG_TABLE_NAME = 'pick_tasks' THEN
        SELECT snapshot.pick_shortage_id
        INTO shortage_id
        FROM public.order_release_allocations snapshot
        WHERE snapshot.tenant_id = NEW.tenant_id
          AND snapshot.inventory_owner_id = NEW.inventory_owner_id
          AND snapshot.facility_id = NEW.facility_id
          AND snapshot.order_release_id = NEW.order_release_id
          AND snapshot.order_id = NEW.order_id
          AND snapshot.order_item_id = NEW.order_item_id
          AND snapshot.reservation_id = NEW.reservation_id
          AND snapshot.allocation_id = NEW.source_allocation_id
          AND snapshot.source_kind = 'shortage_recovery';

        IF shortage_id IS NULL THEN
            RETURN NEW;
        END IF;
    ELSE
        RAISE EXCEPTION 'unsupported pick shortage consistency trigger source'
            USING ERRCODE = '55000';
    END IF;

    SELECT * INTO shortage_row
    FROM public.pick_shortages shortage
    WHERE shortage.tenant_id = NEW.tenant_id
      AND shortage.id = shortage_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'pick shortage lifecycle projection does not exist'
            USING ERRCODE = '23514';
    END IF;

    SELECT COALESCE(SUM(snapshot.planned_qty), 0)::BIGINT,
           COALESCE(SUM(snapshot.planned_qty) FILTER (
               WHERE task.status IN ('completed', 'shorted')
           ), 0)::BIGINT
    INTO reallocated_qty, recovery_terminal_qty
    FROM public.order_release_allocations snapshot
    LEFT JOIN public.pick_tasks task
      ON task.tenant_id = snapshot.tenant_id
     AND task.inventory_owner_id = snapshot.inventory_owner_id
     AND task.facility_id = snapshot.facility_id
     AND task.order_release_id = snapshot.order_release_id
     AND task.order_id = snapshot.order_id
     AND task.order_item_id = snapshot.order_item_id
     AND task.reservation_id = snapshot.reservation_id
     AND task.source_allocation_id = snapshot.allocation_id
    WHERE snapshot.tenant_id = shortage_row.tenant_id
      AND snapshot.inventory_owner_id = shortage_row.inventory_owner_id
      AND snapshot.facility_id = shortage_row.facility_id
      AND snapshot.order_release_id = shortage_row.order_release_id
      AND snapshot.order_id = shortage_row.order_id
      AND snapshot.pick_shortage_id = shortage_row.id
      AND snapshot.source_kind = 'shortage_recovery';

    SELECT COUNT(*),
           MAX(disposition.accepted_short_qty),
           MAX(disposition.resulting_shortage_revision),
           MAX(disposition.resulting_order_revision),
           MAX(disposition.disposed_by_user_id),
           MAX(disposition.disposed_at)
    INTO disposition_count,
         disposition_accepted_short_qty,
         disposition_resulting_shortage_revision,
         disposition_resulting_order_revision,
         disposition_disposed_by_user_id,
         disposition_disposed_at
    FROM public.pick_short_ship_dispositions disposition
    WHERE disposition.tenant_id = shortage_row.tenant_id
      AND disposition.inventory_owner_id = shortage_row.inventory_owner_id
      AND disposition.facility_id = shortage_row.facility_id
      AND disposition.order_release_id = shortage_row.order_release_id
      AND disposition.order_id = shortage_row.order_id
      AND disposition.order_item_id = shortage_row.order_item_id
      AND disposition.reservation_id = shortage_row.reservation_id
      AND disposition.pick_shortage_id = shortage_row.id;

    IF disposition_count = 1
       AND reallocated_qty = recovery_terminal_qty
       AND reallocated_qty < shortage_row.short_qty
       AND disposition_accepted_short_qty = shortage_row.short_qty - reallocated_qty
    THEN
        expected_status := 'resolved';
        expected_resolution := 'short_ship';
        expected_accepted_short_qty := disposition_accepted_short_qty;
    ELSIF disposition_count = 0
       AND reallocated_qty = recovery_terminal_qty
       AND reallocated_qty < shortage_row.short_qty
    THEN
        expected_status := 'awaiting_inventory';
        expected_resolution := NULL;
        expected_accepted_short_qty := 0;
    ELSIF disposition_count = 0
          AND recovery_terminal_qty < reallocated_qty
          AND reallocated_qty <= shortage_row.short_qty
    THEN
        expected_status := 'recovery_in_progress';
        expected_resolution := NULL;
        expected_accepted_short_qty := 0;
    ELSIF disposition_count = 0
          AND recovery_terminal_qty = shortage_row.short_qty
          AND reallocated_qty = shortage_row.short_qty
    THEN
        expected_status := 'resolved';
        expected_resolution := 'recovered';
        expected_accepted_short_qty := 0;
    ELSE
        RAISE EXCEPTION 'pick shortage recovery work does not conserve the shortage quantity'
            USING ERRCODE = '23514';
    END IF;

    SELECT order_header.revision INTO order_revision
    FROM public.orders order_header
    WHERE order_header.tenant_id = shortage_row.tenant_id
      AND order_header.inventory_owner_id = shortage_row.inventory_owner_id
      AND order_header.id = shortage_row.order_id
      AND order_header.deleted IS NULL;

    IF shortage_row.reallocated_qty <> reallocated_qty
       OR shortage_row.recovery_terminal_qty <> recovery_terminal_qty
       OR shortage_row.remaining_to_allocate_qty <> shortage_row.short_qty - reallocated_qty
       OR shortage_row.status <> expected_status
       OR shortage_row.resolution IS DISTINCT FROM expected_resolution
       OR shortage_row.accepted_short_qty <> expected_accepted_short_qty
       OR order_revision < shortage_row.report_resulting_order_revision
       OR (expected_resolution = 'short_ship' AND (
            shortage_row.revision <> disposition_resulting_shortage_revision
            OR shortage_row.resolved_by_user_id <> disposition_disposed_by_user_id
            OR shortage_row.resolved_at <> disposition_disposed_at
            OR order_revision < disposition_resulting_order_revision
       ))
       OR NOT EXISTS (
           SELECT 1
           FROM public.pick_tasks task
           INNER JOIN public.pick_task_contents content
             ON content.tenant_id = task.tenant_id
            AND content.inventory_owner_id = task.inventory_owner_id
            AND content.facility_id = task.facility_id
            AND content.task_id = task.id
           WHERE task.tenant_id = shortage_row.tenant_id
             AND task.inventory_owner_id = shortage_row.inventory_owner_id
             AND task.facility_id = shortage_row.facility_id
             AND task.id = shortage_row.task_id
             AND task.status = 'shorted'
             AND task.completed_at = shortage_row.reported_at
             AND content.id = shortage_row.pick_task_content_id
             AND content.state = 'shorted'
             AND content.completed_at = shortage_row.reported_at
       )
       OR NOT EXISTS (
           SELECT 1 FROM public.inventory_holds discrepancy_hold
           WHERE discrepancy_hold.tenant_id = shortage_row.tenant_id
             AND discrepancy_hold.inventory_owner_id = shortage_row.inventory_owner_id
             AND discrepancy_hold.id = shortage_row.inventory_hold_id
             AND discrepancy_hold.qty = shortage_row.short_qty
             AND discrepancy_hold.reason_code = 'inventory_discrepancy'
             AND discrepancy_hold.reference_type = 'pick_shortage_source'
             AND discrepancy_hold.reference_id = shortage_row.pick_task_content_id
             AND discrepancy_hold.status = 'active'
             AND discrepancy_hold.deleted IS NULL
       )
       OR (shortage_row.picked_qty > 0 AND NOT EXISTS (
           SELECT 1 FROM public.pick_confirmations confirmation
           WHERE confirmation.tenant_id = shortage_row.tenant_id
             AND confirmation.inventory_owner_id = shortage_row.inventory_owner_id
             AND confirmation.id = shortage_row.pick_confirmation_id
             AND confirmation.picked_qty = shortage_row.picked_qty
             AND confirmation.confirmed_at = shortage_row.reported_at
       ))
    THEN
        RAISE EXCEPTION 'pick shortage lifecycle projection is inconsistent with execution records'
            USING ERRCODE = '23514';
    END IF;

    IF TG_TABLE_NAME = 'pick_shortages' THEN
        IF TG_OP = 'INSERT'
           AND order_revision <> shortage_row.report_resulting_order_revision
        THEN
            RAISE EXCEPTION 'pick shortage report did not advance the order revision exactly once'
                USING ERRCODE = '23514';
        END IF;
    END IF;

    IF TG_TABLE_NAME = 'pick_short_ship_dispositions' THEN
        IF shortage_row.revision <> NEW.resulting_shortage_revision
           OR order_revision <> NEW.resulting_order_revision
        THEN
            RAISE EXCEPTION 'short-ship disposition did not advance shortage and order revisions exactly once'
                USING ERRCODE = '23514';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: require_pick_shortage_reallocation_consistency(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.require_pick_shortage_reallocation_consistency() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    run_id BIGINT;
    run_row RECORD;
    snapshot_count BIGINT;
    snapshot_qty BIGINT;
    task_count BIGINT;
    content_count BIGINT;
    shortage_row RECORD;
    order_revision BIGINT;
BEGIN
    IF TG_TABLE_NAME = 'pick_shortage_reallocation_runs' THEN
        run_id := NEW.id;
    ELSIF TG_TABLE_NAME = 'order_release_allocations' THEN
        run_id := NEW.pick_shortage_reallocation_run_id;
    ELSIF TG_TABLE_NAME = 'pick_tasks' THEN
        SELECT snapshot.pick_shortage_reallocation_run_id
        INTO run_id
        FROM public.order_release_allocations snapshot
        WHERE snapshot.tenant_id = NEW.tenant_id
          AND snapshot.inventory_owner_id = NEW.inventory_owner_id
          AND snapshot.facility_id = NEW.facility_id
          AND snapshot.order_release_id = NEW.order_release_id
          AND snapshot.order_id = NEW.order_id
          AND snapshot.order_item_id = NEW.order_item_id
          AND snapshot.reservation_id = NEW.reservation_id
          AND snapshot.allocation_id = NEW.source_allocation_id;
    ELSIF TG_TABLE_NAME = 'pick_task_contents' THEN
        SELECT snapshot.pick_shortage_reallocation_run_id
        INTO run_id
        FROM public.order_release_allocations snapshot
        WHERE snapshot.tenant_id = NEW.tenant_id
          AND snapshot.inventory_owner_id = NEW.inventory_owner_id
          AND snapshot.facility_id = NEW.facility_id
          AND snapshot.order_release_id = NEW.order_release_id
          AND snapshot.order_id = NEW.order_id
          AND snapshot.order_item_id = NEW.order_item_id
          AND snapshot.reservation_id = NEW.reservation_id
          AND snapshot.allocation_id = NEW.source_allocation_id;
    ELSE
        RAISE EXCEPTION 'unsupported pick shortage reallocation trigger source'
            USING ERRCODE = '55000';
    END IF;

    IF run_id IS NULL THEN
        RETURN NEW;
    END IF;

    SELECT * INTO run_row
    FROM public.pick_shortage_reallocation_runs run
    WHERE run.tenant_id = NEW.tenant_id
      AND run.id = run_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'pick shortage reallocation run does not exist'
            USING ERRCODE = '23514';
    END IF;

    SELECT COUNT(*), COALESCE(SUM(snapshot.planned_qty), 0)::BIGINT
    INTO snapshot_count, snapshot_qty
    FROM public.order_release_allocations snapshot
    WHERE snapshot.tenant_id = run_row.tenant_id
      AND snapshot.inventory_owner_id = run_row.inventory_owner_id
      AND snapshot.facility_id = run_row.facility_id
      AND snapshot.order_release_id = run_row.order_release_id
      AND snapshot.order_id = run_row.order_id
      AND snapshot.pick_shortage_id = run_row.pick_shortage_id
      AND snapshot.pick_shortage_reallocation_run_id = run_row.id
      AND snapshot.source_kind = 'shortage_recovery';

    SELECT COUNT(*) INTO task_count
    FROM public.pick_tasks task
    INNER JOIN public.order_release_allocations snapshot
      ON snapshot.tenant_id = task.tenant_id
     AND snapshot.inventory_owner_id = task.inventory_owner_id
     AND snapshot.facility_id = task.facility_id
     AND snapshot.order_release_id = task.order_release_id
     AND snapshot.order_id = task.order_id
     AND snapshot.order_item_id = task.order_item_id
     AND snapshot.reservation_id = task.reservation_id
     AND snapshot.allocation_id = task.source_allocation_id
    WHERE snapshot.tenant_id = run_row.tenant_id
      AND snapshot.pick_shortage_reallocation_run_id = run_row.id;

    SELECT COUNT(*) INTO content_count
    FROM public.pick_task_contents content
    INNER JOIN public.order_release_allocations snapshot
      ON snapshot.tenant_id = content.tenant_id
     AND snapshot.inventory_owner_id = content.inventory_owner_id
     AND snapshot.facility_id = content.facility_id
     AND snapshot.order_release_id = content.order_release_id
     AND snapshot.order_id = content.order_id
     AND snapshot.order_item_id = content.order_item_id
     AND snapshot.reservation_id = content.reservation_id
     AND snapshot.allocation_id = content.source_allocation_id
    WHERE snapshot.tenant_id = run_row.tenant_id
      AND snapshot.pick_shortage_reallocation_run_id = run_row.id;

    SELECT * INTO shortage_row
    FROM public.pick_shortages shortage
    WHERE shortage.tenant_id = run_row.tenant_id
      AND shortage.inventory_owner_id = run_row.inventory_owner_id
      AND shortage.id = run_row.pick_shortage_id;

    SELECT order_header.revision INTO order_revision
    FROM public.orders order_header
    WHERE order_header.tenant_id = run_row.tenant_id
      AND order_header.inventory_owner_id = run_row.inventory_owner_id
      AND order_header.id = run_row.order_id
      AND order_header.deleted IS NULL;

    IF snapshot_count <> run_row.allocation_count
       OR snapshot_qty <> run_row.allocated_qty
       OR task_count <> run_row.allocation_count
       OR content_count <> run_row.allocation_count
       OR shortage_row.id IS NULL
       OR shortage_row.revision < run_row.resulting_shortage_revision
       OR shortage_row.reallocated_qty < shortage_row.short_qty - run_row.remaining_qty
       OR shortage_row.remaining_to_allocate_qty > run_row.remaining_qty
       OR order_revision < run_row.resulting_order_revision
    THEN
        RAISE EXCEPTION 'pick shortage reallocation execution snapshot is incomplete'
            USING ERRCODE = '23514';
    END IF;

    IF TG_TABLE_NAME = 'pick_shortage_reallocation_runs'
       AND (shortage_row.revision <> run_row.resulting_shortage_revision
            OR shortage_row.reallocated_qty <> shortage_row.short_qty - run_row.remaining_qty
            OR shortage_row.remaining_to_allocate_qty <> run_row.remaining_qty
            OR order_revision <> run_row.resulting_order_revision)
    THEN
        RAISE EXCEPTION 'pick shortage reallocation result projection is inconsistent'
            USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$$;


