--
-- Facility shipping-origin configuration lifecycle
--

CREATE TABLE public.facility_shipping_origin_configurations (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    tenant_id bigint NOT NULL,
    facility_id bigint NOT NULL,
    previous_address_id bigint,
    address_id bigint NOT NULL,
    configured_by_user_id bigint NOT NULL,
    configured_at timestamp with time zone NOT NULL,
    expected_revision bigint NOT NULL,
    resulting_revision bigint NOT NULL,
    CONSTRAINT facility_shipping_origin_configurations_revision_check CHECK (
        expected_revision > 0
        AND resulting_revision = expected_revision + 1
        AND resulting_revision > expected_revision
    ),
    CONSTRAINT facility_shipping_origin_configurations_address_change_check CHECK (
        previous_address_id IS NULL OR previous_address_id <> address_id
    ),
    CONSTRAINT facility_shipping_origin_configurations_tenant_id_id_key
        UNIQUE (tenant_id, id),
    CONSTRAINT facility_shipping_origin_configurations_facility_revision_key
        UNIQUE (tenant_id, facility_id, resulting_revision),
    CONSTRAINT facility_shipping_origin_configurations_tenant_id_fkey
        FOREIGN KEY (tenant_id) REFERENCES public.tenants(id),
    CONSTRAINT facility_shipping_origin_configurations_facility_id_fkey
        FOREIGN KEY (tenant_id, facility_id) REFERENCES public.facilities(tenant_id, id),
    CONSTRAINT facility_shipping_origin_configurations_previous_address_id_fkey
        FOREIGN KEY (tenant_id, previous_address_id) REFERENCES public.addresses(tenant_id, id),
    CONSTRAINT facility_shipping_origin_configurations_address_id_fkey
        FOREIGN KEY (tenant_id, address_id) REFERENCES public.addresses(tenant_id, id),
    CONSTRAINT facility_shipping_origin_configurations_actor_id_fkey
        FOREIGN KEY (tenant_id, configured_by_user_id)
        REFERENCES public.tenant_memberships(tenant_id, user_id)
);

ALTER TABLE public.facility_shipping_origin_configurations ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.facility_shipping_origin_configurations FORCE ROW LEVEL SECURITY;

CREATE POLICY facility_shipping_origin_configurations_tenant_isolation
ON public.facility_shipping_origin_configurations
USING (
    tenant_id = NULLIF(current_setting('wareboxes.tenant_id', true), '')::bigint
)
WITH CHECK (
    tenant_id = NULLIF(current_setting('wareboxes.tenant_id', true), '')::bigint
);

CREATE FUNCTION public.guard_facility_shipping_origin_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    origin_is_complete boolean;
BEGIN
    IF OLD.deleted IS NOT NULL
       OR NEW.address_id IS NULL
       OR NEW.address_id IS NOT DISTINCT FROM OLD.address_id
       OR OLD.revision = 9223372036854775807
       OR NEW.revision <> OLD.revision + 1 THEN
        RAISE EXCEPTION
            'facility shipping origin replacement requires a new address and one revision step'
            USING ERRCODE = '55000';
    END IF;

    SELECT (
        address.deleted IS NULL
        AND (
            (
                address.name IS NOT NULL
                AND btrim(address.name) <> ''
                AND address.name = btrim(address.name)
                AND char_length(address.name) <= 200
                AND address.name !~ '[[:cntrl:]]'
            )
            OR (
                address.company IS NOT NULL
                AND btrim(address.company) <> ''
                AND address.company = btrim(address.company)
                AND char_length(address.company) <= 200
                AND address.company !~ '[[:cntrl:]]'
            )
        )
        AND (
            address.name IS NULL
            OR (
                address.name = btrim(address.name)
                AND char_length(address.name) BETWEEN 1 AND 200
                AND address.name !~ '[[:cntrl:]]'
            )
        )
        AND (
            address.company IS NULL
            OR (
                address.company = btrim(address.company)
                AND char_length(address.company) BETWEEN 1 AND 200
                AND address.company !~ '[[:cntrl:]]'
            )
        )
        AND address.line1 = btrim(address.line1)
        AND char_length(address.line1) BETWEEN 1 AND 200
        AND address.line1 !~ '[[:cntrl:]]'
        AND (
            address.line2 IS NULL
            OR (
                address.line2 = btrim(address.line2)
                AND char_length(address.line2) BETWEEN 1 AND 200
                AND address.line2 !~ '[[:cntrl:]]'
            )
        )
        AND address.city IS NOT NULL
        AND address.city = btrim(address.city)
        AND char_length(address.city) BETWEEN 1 AND 100
        AND address.city !~ '[[:cntrl:]]'
        AND (
            address.state IS NULL
            OR (
                address.state = btrim(address.state)
                AND char_length(address.state) BETWEEN 1 AND 100
                AND address.state !~ '[[:cntrl:]]'
            )
        )
        AND address.postal_code IS NOT NULL
        AND address.postal_code = btrim(address.postal_code)
        AND char_length(address.postal_code) BETWEEN 1 AND 32
        AND address.postal_code !~ '[[:cntrl:]]'
        AND address.country = btrim(address.country)
        AND char_length(address.country) BETWEEN 1 AND 100
        AND address.country !~ '[[:cntrl:]]'
        AND (
            address.phone IS NULL
            OR (
                address.phone = btrim(address.phone)
                AND char_length(address.phone) BETWEEN 1 AND 64
                AND address.phone !~ '[[:cntrl:]]'
            )
        )
        AND (
            address.email IS NULL
            OR (
                address.email = btrim(address.email)
                AND char_length(address.email) BETWEEN 1 AND 254
                AND address.email !~ '[[:cntrl:]]'
            )
        )
    )
    INTO origin_is_complete
    FROM public.addresses address
    WHERE address.tenant_id = NEW.tenant_id
      AND address.id = NEW.address_id;

    IF NOT COALESCE(origin_is_complete, false) THEN
        RAISE EXCEPTION 'facility shipping origin address must be complete and valid'
            USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION public.enforce_facility_shipping_origin_audit() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM public.facility_shipping_origin_configurations configuration
        WHERE configuration.tenant_id = NEW.tenant_id
          AND configuration.facility_id = NEW.id
          AND configuration.previous_address_id IS NOT DISTINCT FROM OLD.address_id
          AND configuration.address_id = NEW.address_id
          AND configuration.expected_revision = OLD.revision
          AND configuration.resulting_revision = NEW.revision
    ) THEN
        RAISE EXCEPTION 'facility shipping origin update requires an audit record'
            USING ERRCODE = '55000';
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION public.enforce_facility_shipping_origin_configuration() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM public.facilities facility
        WHERE facility.tenant_id = NEW.tenant_id
          AND facility.id = NEW.facility_id
          AND facility.deleted IS NULL
          AND facility.address_id = NEW.address_id
          AND facility.revision = NEW.resulting_revision
    ) THEN
        RAISE EXCEPTION 'facility shipping origin audit does not match facility state'
            USING ERRCODE = '55000';
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION public.protect_facility_shipping_origin_address() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM public.facilities facility
        WHERE facility.tenant_id = OLD.tenant_id
          AND facility.address_id = OLD.id
    ) OR EXISTS (
        SELECT 1
        FROM public.facility_shipping_origin_configurations configuration
        WHERE configuration.tenant_id = OLD.tenant_id
          AND (
              configuration.previous_address_id = OLD.id
              OR configuration.address_id = OLD.id
          )
    ) THEN
        RAISE EXCEPTION 'facility shipping origin addresses are immutable'
            USING ERRCODE = '55000';
    END IF;
    IF TG_OP = 'UPDATE' THEN
        RETURN NEW;
    END IF;
    RETURN OLD;
END;
$$;

CREATE FUNCTION public.reject_facility_shipping_origin_audit_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
    RAISE EXCEPTION 'facility shipping origin configuration records are immutable'
        USING ERRCODE = '55000';
END;
$$;

CREATE TRIGGER facility_shipping_origin_updates_are_guarded
BEFORE UPDATE OF address_id, revision ON public.facilities
FOR EACH ROW EXECUTE FUNCTION public.guard_facility_shipping_origin_update();

CREATE CONSTRAINT TRIGGER facility_shipping_origin_updates_are_audited
AFTER UPDATE OF address_id, revision ON public.facilities
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION public.enforce_facility_shipping_origin_audit();

CREATE CONSTRAINT TRIGGER facility_shipping_origin_configurations_are_applied
AFTER INSERT ON public.facility_shipping_origin_configurations
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION public.enforce_facility_shipping_origin_configuration();

CREATE TRIGGER facility_shipping_origin_configurations_are_immutable
BEFORE DELETE OR UPDATE ON public.facility_shipping_origin_configurations
FOR EACH ROW EXECUTE FUNCTION public.reject_facility_shipping_origin_audit_mutation();

CREATE TRIGGER facility_shipping_origin_addresses_are_immutable
BEFORE DELETE OR UPDATE ON public.addresses
FOR EACH ROW EXECUTE FUNCTION public.protect_facility_shipping_origin_address();

REVOKE ALL ON FUNCTION public.guard_facility_shipping_origin_update() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.enforce_facility_shipping_origin_audit() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.enforce_facility_shipping_origin_configuration() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.protect_facility_shipping_origin_address() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.reject_facility_shipping_origin_audit_mutation() FROM PUBLIC;

GRANT UPDATE (address_id, revision) ON TABLE public.facilities TO wareboxes_app;
GRANT SELECT,INSERT ON TABLE public.facility_shipping_origin_configurations TO wareboxes_app;
GRANT USAGE ON SEQUENCE public.facility_shipping_origin_configurations_id_seq TO wareboxes_app;


--
-- Optimistic pre-execution fulfillment-order amendments.
--

CREATE TABLE public.order_amendments (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    tenant_id bigint NOT NULL,
    inventory_owner_id bigint NOT NULL,
    order_id bigint NOT NULL,
    previous_address_id bigint NOT NULL,
    resulting_address_id bigint NOT NULL,
    previous_rush boolean NOT NULL,
    resulting_rush boolean NOT NULL,
    previous_ship_by timestamp with time zone,
    resulting_ship_by timestamp with time zone,
    order_status text NOT NULL,
    expected_revision bigint NOT NULL,
    resulting_revision bigint NOT NULL,
    amended_by_user_id bigint NOT NULL,
    amended_at timestamp with time zone NOT NULL,
    CONSTRAINT order_amendments_status_check CHECK (
        order_status IN ('open', 'held')
    ),
    CONSTRAINT order_amendments_revision_check CHECK (
        expected_revision > 0
        AND resulting_revision = expected_revision + 1
        AND resulting_revision > expected_revision
    ),
    CONSTRAINT order_amendments_change_check CHECK (
        previous_address_id <> resulting_address_id
        OR previous_rush IS DISTINCT FROM resulting_rush
        OR previous_ship_by IS DISTINCT FROM resulting_ship_by
    ),
    CONSTRAINT order_amendments_tenant_id_id_key UNIQUE (tenant_id, id),
    CONSTRAINT order_amendments_scope_id_key
        UNIQUE (tenant_id, inventory_owner_id, order_id, id),
    CONSTRAINT order_amendments_order_revision_key
        UNIQUE (tenant_id, inventory_owner_id, order_id, resulting_revision),
    CONSTRAINT order_amendments_tenant_id_fkey
        FOREIGN KEY (tenant_id) REFERENCES public.tenants(id),
    CONSTRAINT order_amendments_order_fkey
        FOREIGN KEY (tenant_id, inventory_owner_id, order_id)
        REFERENCES public.orders(tenant_id, inventory_owner_id, id),
    CONSTRAINT order_amendments_previous_address_fkey
        FOREIGN KEY (tenant_id, previous_address_id)
        REFERENCES public.addresses(tenant_id, id),
    CONSTRAINT order_amendments_resulting_address_fkey
        FOREIGN KEY (tenant_id, resulting_address_id)
        REFERENCES public.addresses(tenant_id, id),
    CONSTRAINT order_amendments_actor_fkey
        FOREIGN KEY (tenant_id, amended_by_user_id)
        REFERENCES public.tenant_memberships(tenant_id, user_id)
);

ALTER TABLE public.order_amendments ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.order_amendments FORCE ROW LEVEL SECURITY;

CREATE POLICY order_amendments_tenant_isolation
ON public.order_amendments
USING (
    tenant_id = NULLIF(current_setting('wareboxes.tenant_id', true), '')::bigint
)
WITH CHECK (
    tenant_id = NULLIF(current_setting('wareboxes.tenant_id', true), '')::bigint
);

CREATE INDEX order_amendments_order_history_idx
ON public.order_amendments
    (tenant_id, inventory_owner_id, order_id, resulting_revision DESC);

CREATE FUNCTION public.guard_fulfillment_order_header_amendment() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
    IF NEW.order_key IS NOT DISTINCT FROM OLD.order_key
       AND NEW.rush IS NOT DISTINCT FROM OLD.rush
       AND NEW.ship_by IS NOT DISTINCT FROM OLD.ship_by
       AND NEW.address_id IS NOT DISTINCT FROM OLD.address_id
    THEN
        RETURN NEW;
    END IF;

    IF OLD.deleted IS NOT NULL
       OR OLD.status NOT IN ('open', 'held')
       OR NEW.status IS DISTINCT FROM OLD.status
       OR NEW.order_key IS DISTINCT FROM OLD.order_key
       OR NEW.inventory_owner_id IS DISTINCT FROM OLD.inventory_owner_id
       OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
       OR OLD.revision = 9223372036854775807
       OR NEW.revision <> OLD.revision + 1
    THEN
        RAISE EXCEPTION
            'fulfillment order header amendments require an open or held order and one revision step'
            USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION public.require_fulfillment_order_header_amendment() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
    IF NEW.rush IS NOT DISTINCT FROM OLD.rush
       AND NEW.ship_by IS NOT DISTINCT FROM OLD.ship_by
       AND NEW.address_id IS NOT DISTINCT FROM OLD.address_id
    THEN
        RETURN NULL;
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.order_amendments amendment
        WHERE amendment.tenant_id = NEW.tenant_id
          AND amendment.inventory_owner_id = NEW.inventory_owner_id
          AND amendment.order_id = NEW.id
          AND amendment.previous_address_id = OLD.address_id
          AND amendment.resulting_address_id = NEW.address_id
          AND amendment.previous_rush = OLD.rush
          AND amendment.resulting_rush = NEW.rush
          AND amendment.previous_ship_by IS NOT DISTINCT FROM OLD.ship_by
          AND amendment.resulting_ship_by IS NOT DISTINCT FROM NEW.ship_by
          AND amendment.order_status = NEW.status
          AND amendment.expected_revision = OLD.revision
          AND amendment.resulting_revision = NEW.revision
    ) THEN
        RAISE EXCEPTION 'fulfillment order header update requires exact amendment evidence'
            USING ERRCODE = '55000';
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION public.require_fulfillment_order_amendment_state() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM public.orders order_header
        WHERE order_header.tenant_id = NEW.tenant_id
          AND order_header.inventory_owner_id = NEW.inventory_owner_id
          AND order_header.id = NEW.order_id
          AND order_header.deleted IS NULL
          AND order_header.status = NEW.order_status
          AND order_header.address_id = NEW.resulting_address_id
          AND order_header.rush = NEW.resulting_rush
          AND order_header.ship_by IS NOT DISTINCT FROM NEW.resulting_ship_by
          AND order_header.revision = NEW.resulting_revision
    ) THEN
        RAISE EXCEPTION 'fulfillment order amendment does not match resulting order state'
            USING ERRCODE = '55000';
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION public.reject_fulfillment_order_amendment_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
    RAISE EXCEPTION 'fulfillment order amendment evidence is immutable'
        USING ERRCODE = '55000';
END;
$$;

CREATE FUNCTION public.protect_fulfillment_order_amendment_address() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM public.order_amendments amendment
        WHERE amendment.tenant_id = OLD.tenant_id
          AND (
              amendment.previous_address_id = OLD.id
              OR amendment.resulting_address_id = OLD.id
          )
    ) THEN
        RAISE EXCEPTION 'fulfillment order amendment addresses are immutable'
            USING ERRCODE = '55000';
    END IF;
    IF TG_OP = 'UPDATE' THEN
        RETURN NEW;
    END IF;
    RETURN OLD;
END;
$$;

CREATE TRIGGER orders_guard_header_amendments
BEFORE UPDATE OF order_key, rush, ship_by, address_id, status, revision ON public.orders
FOR EACH ROW EXECUTE FUNCTION public.guard_fulfillment_order_header_amendment();

CREATE CONSTRAINT TRIGGER orders_require_header_amendments
AFTER UPDATE OF rush, ship_by, address_id, status, revision ON public.orders
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION public.require_fulfillment_order_header_amendment();

CREATE CONSTRAINT TRIGGER order_amendments_require_resulting_state
AFTER INSERT ON public.order_amendments
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION public.require_fulfillment_order_amendment_state();

CREATE TRIGGER order_amendments_are_immutable
BEFORE DELETE OR UPDATE ON public.order_amendments
FOR EACH ROW EXECUTE FUNCTION public.reject_fulfillment_order_amendment_mutation();

CREATE TRIGGER order_amendment_addresses_are_immutable
BEFORE DELETE OR UPDATE ON public.addresses
FOR EACH ROW EXECUTE FUNCTION public.protect_fulfillment_order_amendment_address();

REVOKE ALL ON FUNCTION public.guard_fulfillment_order_header_amendment() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.require_fulfillment_order_header_amendment() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.require_fulfillment_order_amendment_state() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.reject_fulfillment_order_amendment_mutation() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.protect_fulfillment_order_amendment_address() FROM PUBLIC;

REVOKE UPDATE ON TABLE public.orders FROM wareboxes_app;
GRANT UPDATE (
    deleted, rush, status, address_id, revision, confirmed, closed, ship_by, wave_id
) ON TABLE public.orders TO wareboxes_app;
GRANT SELECT,INSERT ON TABLE public.order_amendments TO wareboxes_app;
GRANT USAGE ON SEQUENCE public.order_amendments_id_seq TO wareboxes_app;


--
-- Typed outbound-load execution and movable packed-carton projection.

ALTER TABLE ONLY public.carton_contents
    ADD CONSTRAINT carton_contents_scope_id_key
    UNIQUE (tenant_id, inventory_owner_id, facility_id, carton_id, id);

CREATE TABLE public.packed_inventory_positions (
    id bigint NOT NULL,
    tenant_id bigint NOT NULL,
    inventory_owner_id bigint NOT NULL,
    facility_id bigint NOT NULL,
    carton_id bigint NOT NULL,
    carton_content_id bigint NOT NULL,
    reservation_id bigint NOT NULL,
    item_batch_id bigint NOT NULL,
    item_id bigint NOT NULL,
    uom text NOT NULL,
    inventory_status text NOT NULL,
    packed_qty bigint NOT NULL,
    state text DEFAULT 'packed' NOT NULL,
    outbound_load_id bigint,
    outbound_load_carton_id bigint,
    load_sequence bigint,
    current_inventory_allocation_id bigint,
    current_inventory_balance_id bigint,
    current_location_id bigint,
    current_license_plate_id bigint,
    revision bigint DEFAULT 1 NOT NULL,
    positioned_at timestamp with time zone NOT NULL,
    departure_inventory_transaction_id bigint,
    departed_at timestamp with time zone,
    CONSTRAINT packed_inventory_positions_pkey PRIMARY KEY (id),
    CONSTRAINT packed_inventory_positions_content_key UNIQUE
        (tenant_id, inventory_owner_id, facility_id, carton_id, carton_content_id),
    CONSTRAINT packed_inventory_positions_scope_id_key UNIQUE
        (tenant_id, inventory_owner_id, facility_id, carton_id, id),
    CONSTRAINT packed_inventory_positions_qty_check CHECK (packed_qty > 0),
    CONSTRAINT packed_inventory_positions_revision_check CHECK (revision > 0),
    CONSTRAINT packed_inventory_positions_state_check CHECK
        (state IN ('packed', 'staged', 'loaded', 'departed')),
    CONSTRAINT packed_inventory_positions_load_sequence_check CHECK
        (load_sequence IS NULL OR load_sequence > 0),
    CONSTRAINT packed_inventory_positions_fields_check CHECK (
        (state = 'packed'
            AND outbound_load_id IS NULL AND outbound_load_carton_id IS NULL
            AND load_sequence IS NULL
            AND current_inventory_allocation_id IS NOT NULL
            AND current_inventory_balance_id IS NOT NULL
            AND current_location_id IS NOT NULL
            AND current_license_plate_id IS NOT NULL
            AND departure_inventory_transaction_id IS NULL AND departed_at IS NULL)
        OR (state = 'staged'
            AND outbound_load_id IS NOT NULL AND outbound_load_carton_id IS NOT NULL
            AND load_sequence IS NOT NULL
            AND current_inventory_allocation_id IS NOT NULL
            AND current_inventory_balance_id IS NOT NULL
            AND current_location_id IS NOT NULL
            AND current_license_plate_id IS NOT NULL
            AND departure_inventory_transaction_id IS NULL AND departed_at IS NULL)
        OR (state = 'loaded'
            AND outbound_load_id IS NOT NULL AND outbound_load_carton_id IS NOT NULL
            AND load_sequence IS NOT NULL
            AND current_inventory_allocation_id IS NOT NULL
            AND current_inventory_balance_id IS NOT NULL
            AND current_location_id IS NOT NULL
            AND current_license_plate_id IS NOT NULL
            AND departure_inventory_transaction_id IS NULL AND departed_at IS NULL)
        OR (state = 'departed'
            AND ((outbound_load_id IS NULL AND outbound_load_carton_id IS NULL AND load_sequence IS NULL)
                 OR (outbound_load_id IS NOT NULL AND outbound_load_carton_id IS NOT NULL AND load_sequence IS NOT NULL))
            AND current_inventory_allocation_id IS NULL
            AND current_inventory_balance_id IS NULL
            AND current_location_id IS NULL
            AND current_license_plate_id IS NULL
            AND departure_inventory_transaction_id IS NOT NULL AND departed_at IS NOT NULL)
    ),
    CONSTRAINT packed_inventory_positions_uom_check CHECK
        (uom = btrim(uom) AND uom <> ''),
    CONSTRAINT packed_inventory_positions_inventory_status_check CHECK
        (inventory_status = 'available')
);
ALTER TABLE ONLY public.packed_inventory_positions FORCE ROW LEVEL SECURITY;

CREATE TABLE public.outbound_loads (
    id bigint GENERATED ALWAYS AS IDENTITY
        (SEQUENCE NAME public.outbound_loads_id_seq) NOT NULL,
    tenant_id bigint NOT NULL,
    facility_id bigint NOT NULL,
    load_reference text NOT NULL,
    load_barcode text NOT NULL,
    carrier text NOT NULL,
    state text DEFAULT 'planned' NOT NULL,
    revision bigint DEFAULT 1 NOT NULL,
    staging_lane_location_id bigint NOT NULL,
    dock_door_location_id bigint,
    virtual_trailer_location_id bigint NOT NULL,
    trailer_number text,
    seal_number text,
    scheduled_departure_at timestamp with time zone,
    shipment_count bigint NOT NULL,
    carton_count bigint NOT NULL,
    planned_by_user_id bigint NOT NULL,
    planned_at timestamp with time zone NOT NULL,
    released_by_user_id bigint,
    released_at timestamp with time zone,
    loading_started_by_user_id bigint,
    loading_started_at timestamp with time zone,
    ready_to_depart_by_user_id bigint,
    ready_to_depart_at timestamp with time zone,
    departed_by_user_id bigint,
    departed_at timestamp with time zone,
    cancelled_by_user_id bigint,
    cancelled_at timestamp with time zone,
    CONSTRAINT outbound_loads_pkey PRIMARY KEY (id),
    CONSTRAINT outbound_loads_tenant_id_id_key UNIQUE (tenant_id, id),
    CONSTRAINT outbound_loads_scope_id_key UNIQUE (tenant_id, facility_id, id),
    CONSTRAINT outbound_loads_reference_key UNIQUE (tenant_id, load_reference),
    CONSTRAINT outbound_loads_barcode_key UNIQUE (tenant_id, load_barcode),
    CONSTRAINT outbound_loads_counts_check CHECK (shipment_count > 0 AND carton_count > 0),
    CONSTRAINT outbound_loads_revision_check CHECK (revision > 0),
    CONSTRAINT outbound_loads_state_check CHECK
        (state IN ('planned', 'staging', 'loading', 'ready_to_depart', 'departed', 'cancelled')),
    CONSTRAINT outbound_loads_reference_check CHECK
        (load_reference = btrim(load_reference) AND load_reference <> '' AND char_length(load_reference) <= 100),
    CONSTRAINT outbound_loads_barcode_check CHECK
        (load_barcode = btrim(load_barcode) AND load_barcode <> '' AND char_length(load_barcode) <= 200),
    CONSTRAINT outbound_loads_carrier_check CHECK
        (carrier = btrim(carrier) AND carrier <> '' AND char_length(carrier) <= 100),
    CONSTRAINT outbound_loads_trailer_check CHECK
        (trailer_number IS NULL OR (trailer_number = btrim(trailer_number) AND trailer_number <> '' AND char_length(trailer_number) <= 100)),
    CONSTRAINT outbound_loads_seal_check CHECK
        (seal_number IS NULL OR (seal_number = btrim(seal_number) AND seal_number <> '' AND char_length(seal_number) <= 100))
);
ALTER TABLE ONLY public.outbound_loads FORCE ROW LEVEL SECURITY;

CREATE TABLE public.outbound_load_shipments (
    id bigint GENERATED ALWAYS AS IDENTITY
        (SEQUENCE NAME public.outbound_load_shipments_id_seq) NOT NULL,
    tenant_id bigint NOT NULL,
    inventory_owner_id bigint NOT NULL,
    facility_id bigint NOT NULL,
    outbound_load_id bigint NOT NULL,
    shipment_id bigint NOT NULL,
    order_id bigint NOT NULL,
    shipment_sequence bigint NOT NULL,
    expected_shipment_revision bigint NOT NULL,
    expected_order_revision bigint NOT NULL,
    carton_count bigint NOT NULL,
    shipped_qty bigint NOT NULL,
    carrier text NOT NULL,
    closed_at timestamp with time zone,
    CONSTRAINT outbound_load_shipments_pkey PRIMARY KEY (id),
    CONSTRAINT outbound_load_shipments_scope_id_key UNIQUE
        (tenant_id, inventory_owner_id, facility_id, outbound_load_id, id),
    CONSTRAINT outbound_load_shipments_load_shipment_key UNIQUE
        (tenant_id, outbound_load_id, shipment_id),
    CONSTRAINT outbound_load_shipments_load_sequence_key UNIQUE
        (tenant_id, outbound_load_id, shipment_sequence),
    CONSTRAINT outbound_load_shipments_counts_check CHECK
        (shipment_sequence > 0 AND carton_count > 0 AND shipped_qty > 0),
    CONSTRAINT outbound_load_shipments_revisions_check CHECK
        (expected_shipment_revision > 0 AND expected_order_revision > 0),
    CONSTRAINT outbound_load_shipments_carrier_check CHECK
        (carrier = btrim(carrier) AND carrier <> '' AND char_length(carrier) <= 100)
);
ALTER TABLE ONLY public.outbound_load_shipments FORCE ROW LEVEL SECURITY;

CREATE TABLE public.outbound_load_cartons (
    id bigint GENERATED ALWAYS AS IDENTITY
        (SEQUENCE NAME public.outbound_load_cartons_id_seq) NOT NULL,
    tenant_id bigint NOT NULL,
    inventory_owner_id bigint NOT NULL,
    facility_id bigint NOT NULL,
    outbound_load_id bigint NOT NULL,
    outbound_load_shipment_id bigint NOT NULL,
    shipment_id bigint NOT NULL,
    shipment_carton_id bigint NOT NULL,
    carton_id bigint NOT NULL,
    license_plate_id bigint NOT NULL,
    carton_barcode text NOT NULL,
    shipment_sequence bigint NOT NULL,
    load_sequence bigint NOT NULL,
    original_location_id bigint NOT NULL,
    content_count bigint NOT NULL,
    packed_qty bigint NOT NULL,
    state text DEFAULT 'planned' NOT NULL,
    revision bigint DEFAULT 1 NOT NULL,
    last_move_confirmation_id bigint,
    staged_at timestamp with time zone,
    loaded_at timestamp with time zone,
    departed_at timestamp with time zone,
    closed_at timestamp with time zone,
    CONSTRAINT outbound_load_cartons_pkey PRIMARY KEY (id),
    CONSTRAINT outbound_load_cartons_scope_id_key UNIQUE
        (tenant_id, inventory_owner_id, facility_id, outbound_load_id, id),
    CONSTRAINT outbound_load_cartons_load_carton_key UNIQUE
        (tenant_id, outbound_load_id, carton_id),
    CONSTRAINT outbound_load_cartons_load_sequence_key UNIQUE
        (tenant_id, outbound_load_id, load_sequence),
    CONSTRAINT outbound_load_cartons_counts_check CHECK
        (shipment_sequence > 0 AND load_sequence > 0 AND content_count > 0 AND packed_qty > 0),
    CONSTRAINT outbound_load_cartons_revision_check CHECK (revision > 0),
    CONSTRAINT outbound_load_cartons_state_check CHECK
        (state IN ('planned', 'staged', 'loaded', 'departed')),
    CONSTRAINT outbound_load_cartons_barcode_check CHECK
        (carton_barcode = btrim(carton_barcode) AND carton_barcode <> '' AND char_length(carton_barcode) <= 200)
);
ALTER TABLE ONLY public.outbound_load_cartons FORCE ROW LEVEL SECURITY;

CREATE TABLE public.packed_carton_move_confirmations (
    id bigint GENERATED ALWAYS AS IDENTITY
        (SEQUENCE NAME public.packed_carton_move_confirmations_id_seq) NOT NULL,
    tenant_id bigint NOT NULL,
    inventory_owner_id bigint NOT NULL,
    facility_id bigint NOT NULL,
    outbound_load_id bigint NOT NULL,
    outbound_load_carton_id bigint NOT NULL,
    carton_id bigint NOT NULL,
    license_plate_id bigint NOT NULL,
    movement_kind text NOT NULL,
    inventory_transaction_id bigint NOT NULL,
    expected_position_revision bigint NOT NULL,
    resulting_position_revision bigint NOT NULL,
    expected_load_revision bigint NOT NULL,
    resulting_load_revision bigint NOT NULL,
    source_location_id bigint NOT NULL,
    destination_location_id bigint NOT NULL,
    detail_count bigint NOT NULL,
    moved_qty bigint NOT NULL,
    moved_by_user_id bigint NOT NULL,
    moved_at timestamp with time zone NOT NULL,
    CONSTRAINT packed_carton_move_confirmations_pkey PRIMARY KEY (id),
    CONSTRAINT packed_carton_move_confirmations_scope_id_key UNIQUE
        (tenant_id, inventory_owner_id, facility_id, outbound_load_id, outbound_load_carton_id, id),
    CONSTRAINT packed_carton_move_confirmations_transaction_key UNIQUE
        (tenant_id, inventory_owner_id, inventory_transaction_id),
    CONSTRAINT packed_carton_move_confirmations_revision_key UNIQUE
        (tenant_id, outbound_load_carton_id, resulting_position_revision),
    CONSTRAINT packed_carton_move_confirmations_kind_check CHECK
        (movement_kind IN ('stage', 'load', 'unload', 'unstage')),
    CONSTRAINT packed_carton_move_confirmations_counts_check CHECK
        (detail_count > 0 AND moved_qty > 0),
    CONSTRAINT packed_carton_move_confirmations_revisions_check CHECK
        (expected_position_revision > 0
         AND resulting_position_revision = expected_position_revision + 1
         AND expected_load_revision > 0
         AND resulting_load_revision IN (expected_load_revision, expected_load_revision + 1)),
    CONSTRAINT packed_carton_move_confirmations_locations_check CHECK
        (source_location_id <> destination_location_id)
);
ALTER TABLE ONLY public.packed_carton_move_confirmations FORCE ROW LEVEL SECURITY;

CREATE TABLE public.packed_carton_move_details (
    id bigint GENERATED ALWAYS AS IDENTITY
        (SEQUENCE NAME public.packed_carton_move_details_id_seq) NOT NULL,
    tenant_id bigint NOT NULL,
    inventory_owner_id bigint NOT NULL,
    facility_id bigint NOT NULL,
    move_confirmation_id bigint NOT NULL,
    carton_id bigint NOT NULL,
    packed_position_id bigint NOT NULL,
    carton_content_id bigint NOT NULL,
    reservation_id bigint NOT NULL,
    item_batch_id bigint NOT NULL,
    item_id bigint NOT NULL,
    uom text NOT NULL,
    inventory_status text NOT NULL,
    source_inventory_allocation_id bigint NOT NULL,
    destination_inventory_allocation_id bigint NOT NULL,
    source_inventory_balance_id bigint NOT NULL,
    destination_inventory_balance_id bigint NOT NULL,
    quantity bigint NOT NULL,
    CONSTRAINT packed_carton_move_details_pkey PRIMARY KEY (id),
    CONSTRAINT packed_carton_move_details_confirmation_position_key UNIQUE
        (tenant_id, move_confirmation_id, packed_position_id),
    CONSTRAINT packed_carton_move_details_allocations_check CHECK
        (source_inventory_allocation_id <> destination_inventory_allocation_id),
    CONSTRAINT packed_carton_move_details_balances_check CHECK
        (source_inventory_balance_id <> destination_inventory_balance_id),
    CONSTRAINT packed_carton_move_details_qty_check CHECK (quantity > 0),
    CONSTRAINT packed_carton_move_details_uom_check CHECK
        (uom = btrim(uom) AND uom <> ''),
    CONSTRAINT packed_carton_move_details_inventory_status_check CHECK
        (inventory_status = 'available')
);
ALTER TABLE ONLY public.packed_carton_move_details FORCE ROW LEVEL SECURITY;

CREATE TABLE public.outbound_load_cancellations (
    id bigint GENERATED ALWAYS AS IDENTITY
        (SEQUENCE NAME public.outbound_load_cancellations_id_seq) NOT NULL,
    tenant_id bigint NOT NULL,
    facility_id bigint NOT NULL,
    outbound_load_id bigint NOT NULL,
    expected_revision bigint NOT NULL,
    resulting_revision bigint NOT NULL,
    reason_code text NOT NULL,
    note text,
    cancelled_by_user_id bigint NOT NULL,
    cancelled_at timestamp with time zone NOT NULL,
    CONSTRAINT outbound_load_cancellations_pkey PRIMARY KEY (id),
    CONSTRAINT outbound_load_cancellations_load_key UNIQUE (tenant_id, outbound_load_id),
    CONSTRAINT outbound_load_cancellations_revision_check CHECK
        (expected_revision > 0 AND resulting_revision = expected_revision + 1),
    CONSTRAINT outbound_load_cancellations_reason_check CHECK
        (reason_code IN ('route_cancelled', 'carrier_cancelled', 'equipment_unavailable', 'planning_error', 'other')),
    CONSTRAINT outbound_load_cancellations_note_check CHECK
        (note IS NULL OR (note = btrim(note) AND note <> '' AND char_length(note) <= 500)),
    CONSTRAINT outbound_load_cancellations_other_note_check CHECK
        (reason_code <> 'other' OR note IS NOT NULL)
);
ALTER TABLE ONLY public.outbound_load_cancellations FORCE ROW LEVEL SECURITY;

